window.LAW_DATA = {"id": "istithmar", "title": "قانون الاستثمار", "title_en": "INVESTMENT LAW", "cat": "تجاري", "icon": "📈", "desc": "القانون رقم 72 لسنة 2017 — الضمانات والحوافز الخاصة بالاستثمار في مصر.", "article_count": 104, "articles": [{"number": "الأولى", "chapter": "", "text": "يعمل في شأن الاستثمار في جمهورية مصر العربية بأحكام القانون المرافق . وتسري أحكامه على الاستثمار المحلي والأجنبي أيا كان حجمه، ويكون الاستثمار وفقا لأحكام هذا القانون، إما بنظام الاستثمار الداخلي، أو بنظام المناطق الاستثمارية أو بنظام المناطق التكنولوجية، أو بنظام المناطق الحرة ."}, {"number": "الثانية", "chapter": "", "text": "لا تخل أحكام القانون المرافق بالمزايا والإعفاءات الضريبية وغيرها من الضمانات والحوافز المقررة للشركات والمنشآت القائمة وقت العمل به، وتظل هذه الشركات والمنشآت محتفظة بتلك المزايا والإعفاءات والضمانات والحوافز إلى أن تنتهي المدد الخاصة بها، وذلك طبقا للتشريعات والاتفاقيات المستمدة منها . ولا تخل أحكام القانون المرافق بأحكام القانون رقم 7 لسنة 1991 بشأن أملاك الدولة الخاصة، وقانون المناطق الاقتصادية ذات الطبيعة الخاصة الصادر بالقانون رقم 83 لسنة 2002، والقانون رقم 14 لسنة 2012 في شأن التنمية المتكاملة في شبه جزيرة سيناء، وقانون تيسير إجراءات منح تراخيص المنشآت الصناعية الصادر بالقانون رقم 15 لسنة 2017 . كما لا تخل أحكام القانون المرافق بالشروط الموضوعية المقررة لمنح الموافقات والتصاريح والتراخيص المنصوص عليها في أي قوانين أخرى ."}, {"number": "الثالثة", "chapter": "", "text": "تستبدل عبارة (قانون الاستثمار) بعبارة (قانون ضمانات وحوافز الاستثمار)، أينما وردت في القوانين والقرارات الأخرى ."}, {"number": "الرابعة", "chapter": "", "text": "تستثنى شركات المساهمة الخاضعة لأحكام هذا القانون من تطبيق أحكام القانون رقم 113 لسنة 1958 في شأن التعيين في وظائف شركات المساهمة والمؤسسات العامة . كما لا تخضع شركات المساهمة لأحكام القانون رقم 73 لسنة 1973 بشأن تحديد شروط وإجراءات انتخاب ممثلي العمال في مجالس إدارة وحدات القطاع العام والشركات المساهمة والجمعيات والمؤسسات الخاصة، ويبين نظام الشركة طريقة اشتراك العاملين في إدارتها ."}, {"number": "الخامسة", "chapter": "", "text": "تستثنى المنازعات الناشئة عن تطبيق أحكام هذا القانون والقانون المرافق له، من الخضوع لأحكام القانون رقم 7 لسنة 2000 بإنشاء لجان التوفيق في بعض المنازعات التي تكون الوزارات والأشخاص الاعتبارية العامة طرفا فيها ."}, {"number": "السادسة", "chapter": "", "text": "تحال التظلمات والطلبات المنظورة أمام لجنتي فض منازعات الاستثمار وتسوية منازعات عقود الاستثمار القائمتين، إلى اللجنتين المنصوص عليهما في المادتين 85 ، 88 من القانون المرافق فور تشكيلهما دون الحاجة إلى أي إجراء آخر ."}, {"number": "السابعة", "chapter": "", "text": "يستمر العاملون المخاطبون بحكم الفقرة الثالثة من المادة (20) من قانون الاستثمار الصادر بالقانون رقم 230 لسنة 1989 في التمتع بذات الأوضاع المقررة لهم، ولا تخل هذه الأحكام بنظام توزيع الأرباح المطبق على الشركات القائمة وقت نفاذ هذا القانون إذا كان ذلك أفضل لهم ."}, {"number": "الثامنة", "chapter": "", "text": "يلغى قانون ضمانات وحوافز الاستثمار الصادر بالقانون رقم 8 لسنة 1997، كما يلغى كل حكم يخالف أحكام هذا القانون والقانون المرافق له ."}, {"number": "التاسعة", "chapter": "", "text": "يصدر رئيس مجلس الوزراء اللائحة التنفيذية للقانون المرافق، بناء على عرض الوزير المختص وبعد موافقة مجلس الوزراء خلال تسعين يوما من تاريخ العمل بهذا القانون، وإلى أن تصدر هذه اللائحة يستمر العمل باللوائح والقرارات السارية في تاريخ العمل به فيما لا يتعارض مع أحكامه ."}, {"number": "العاشرة", "chapter": "", "text": "ينشر هذا القانون في الجريدة الرسمية، ويعمل به من اليوم التالي لتاريخ نشره . يبصم هذا القانون بخاتم الدولة، وينفذ كقانون من قوانينها . صدر برئاسة الجمهورية فى 5 رمضان سنة 1438 هـ الموافق 31 مايو سنة 2017 م عبد الفتاح السيسى قانون الاستثمار"}, {"number": "1", "chapter": "الفصل الأول", "text": "في تطبيق أحكام هذا القانون، يقصد بالكلمات والعبارات التالية المعاني المبينة قرين كل منها : الاستثمار: استخدام المال لإنشاء مشروع استثماري أو توسيعه أو تطويره أو تمويله أو تملكه أو إدارته بما يسهم في تحقيق التنمية الشاملة والمستدامة للبلاد . المستثمر: كل شخص طبيعي أو اعتباري، مصريا كان أو أجنبيا، أيا كان النظام القانوني الخاضع له، يقوم بالاستثمار في جمهورية مصر العربية وفقا لأحكام هذا القانون . المشروع الاستثماري: مزاولة أحد الأنشطة الاستثمارية في قطاعات الصناعة والزراعة والتجارة والتعليم والصحة والنقل والسياحة والإسكان والتشييد والبناء والرياضة والكهرباء والطاقة والثروات الطبيعية والمياه والاتصالات والتكنولوجيا . ويجوز للوزير المختص بشئون الاستثمار بالتنسيق مع الوزارة أو الوزارات المعنية إضافة قطاعات أخرى وفقا لخطة التنمية الاقتصادية للدولة، وتبين اللائحة التنفيذية لهذا القانون شروط ونطاق وضوابط مزاولة هذه الأنشطة . الحوافز الخاصة: الحوافز المنصوص عليها في المادة (11) من هذا القانون . الأموال: جميع أنواع الأصول التي تدخل في المشروع الاستثماري أيا كان نوعها، وتكون لها قيمة مادية، سواء كانت نقدية أو عينية أو معنوية، وتشمل على الأخص : 1- الأموال الثابتة والمنقولة، وكذلك أي حقوق عينية أصلية أو تبعية أخرى . 2- الأسهم وحصص تأسيس الشركات، والسندات غير الحكومية . 3- حقوق الملكية الفكرية والحقوق المعنوية التي تستخدم في إنشاء المشروعات أو التوسع فيها، كبراءات الاختراع والعلامات والأسماء التجارية المسجلة في دولة من دول المنظمة العالمية للملكية الفكرية أو وفقا لقواعد التسجيل الدولية التي تضمنتها الاتفاقيات الدولية النافذة في هذا الشأن . 4- الامتيازات أو العقود التي تمنح بمقتضى قوانين التزامات المرافق العامة والقوانين ذات الطبيعة المماثلة لها، وكذلك جميع الحقوق المماثلة الأخرى التي تعطى بناء على القانون . المجلس الأعلى: المجلس الأعلى للاستثمار . الوزير المختص: الوزير المختص بشئون الاستثمار . الوزارة المختصة: الوزارة المختصة بشئون الاستثمار . الهيئة: الهيئة العامة للاستثمار والمناطق الحرة . الاستثمار الداخلي: أحد نظم الاستثمار يتم من خلاله إقامة أو إنشاء أو تشغيل مشروع استثماري وفقا لأحكام هذا القانون، في غير المناطق الحرة . المنطقة الحرة: جزء من إقليم الدولة يدخل ضمن حدودها ويخضع لسلطاتها الإدارية ويتم التعامل فيه وفقا لأحكام جمركية وضريبية خاصة . المنطقة الاستثمارية: منطقة جغرافية محددة المساحة والحدود، تخصص لإقامة نشاط معين أو أكثر من الأنشطة الاستثمارية المتخصصة وغيرها من الأنشطة المكملة لها، يقوم على تنميتها ووضع بنيتها الأساسية مطور لتلك المنطقة . المطور: كل شخص اعتباري يرخص له إنشاء منطقة استثمارية أو إدارتها أو تطويرها أو تنميتها وفقا لأحكام هذا القانون . الجهات المختصة: الجهات الإدارية أو شركات المرافق العامة المختصة بإصدار الموافقات أو التصاريح أو التراخيص . مركز خدمات المستثمرين: وحدة إدارية منشأة بالهيئة أو أحد فروعها تتولى تطبيق نظام لتيسير وتبسيط إجراءات حصول المستثمر على جميع الموافقات والتصاريح والتراخيص اللازمة لمشروعه الاستثماري خلال المدد القانونية المنصوص عليها في هذا القانون، وإتاحة ما يلزم لذلك من بيانات ومعلومات . ممثل الجهة المختصة: المسئول المنتدب من الجهات الإدارية المختصة أو المكلف من شركات المرافق العامة، للعمل في نظام مركز خدمات المستثمرين بالهيئة أو أحد فروعها، والذي تنتقل إليه بموجب أحكام هذا القانون سلطة إصدار الموافقات والتصاريح والتراخيص، بحسب الاشتراطات الفنية الواردة بالقوانين المنظمة لها ودليل إجراءات الاستثمار الذي تصدره الهيئة، وكذا جميع الصلاحيات المقررة للسلطة المختصة في مجال تخصيص العقارات وإعطاء الموافقات والتصاريح والتراخيص اللازمة لتبسيط عمل المستثمر وتيسيره، وتشجيع الاستثمار وتنميته . السلطة المختصة: الوزير أو المحافظ أو رئيس الهيئة أو المصلحة أو مجلس إدارتها أو رئيس مجلس إدارة شركة الموافق العامة أو مجلس إدارتها، بحسب الأحوال . مكاتب الاعتماد: المكاتب المرخص لها من الهيئة بمنح الموافقات والتصاريح والتراخيص، بالعمل في مجال فحص الإجراءات والمستندات الخاصة بالمشروعات الاستثمارية وتقديم شهادات الاعتماد ."}, {"number": "2", "chapter": "الفصل الثاني", "text": "يهدف الاستثمار في جمهورية مصر العربية إلى رفع معدلات النمو الاقتصادي للبلاد، وزيادة معدلات الإنتاج المحلي وتوفير فرص العمل، وتشجيع التصدير، وزيادة التنافسية، بما يسهم في تحقيق التنمية الشاملة والمستدامة . وتعمل جميع أجهزة الدولة المختصة على جذب وتحفيز الاستثمارات المحلية والأجنبية . ويحكم الاستثمار المبادئ الآتية : 1- المساواة في الفرص الاستثمارية ومراعاة تكافؤ الفرص بغض النظر عن حجم المشروع ومكانه ودون تمييز بسبب الجنس . 2 - دعم الدولة للشركات الناشئة وزيادة الأعمال والمشروعات متناهية الصغر والصغيرة والمتوسطة لتمكين الشباب وصغار المستثمرين . 3- مراعاة جميع النواحي ذات البعد الاجتماعي وحماية البيئة والصحة العامة . 4- حرية المنافسة ومنع الممارسات الاحتكارية وحماية المستهلك . 5- إتباع مبادئ الحوكمة والشفافية والإدارة الرشيدة وعدم تضارب المصالح . 6- العمل على استقرار السياسات الاستثمارية وثابتها . 7- سرعة إنجاز معاملات المستثمرين والتيسير عليهم بما يحقق مصالحهم المشروعة . 8- حق الدولة في الحفاظ على الأمن القومي والمصلحة العامة . وتسري مبادئ الاستثمار المشار إليها على المستثمر والدولة كل فيما يخصه ."}, {"number": "3", "chapter": "الفصل الأول", "text": "تتمتع جميع الاستثمارات المقامة في جمهورية مصر العربية بالمعاملة العادلة والمنصفة . وتكفل الدولة للمستثمر الأجنبي معاملة مماثلة لتلك التي تمنحها للمستثمر الوطني . ويجوز استثناء بقرار من مجلس الوزراء تقرير معاملة تفضيلية للمستثمرين الأجانب تطبيقا لمبدأ المعاملة بالمثل . ولا تخضع الأموال المستثمرة لأي إجراءات تعسفية أو قرارات تتسم بالتمييز . وتمنح الدولة المستثمرين غير المصريين إقامة في جمهورية مصر العربية طوال مدة المشروع، وذلك دون الإخلال بأحكام القوانين المنظمة لذلك وعلى النحو الذي تبينه اللائحة التنفيذية لهذا القانون . وتلتزم الدولة باحترام وإنفاذ العقود التي تبرمها، ولا يتمتع المشروع الاستثماري المقام بناء على غش أو تدليس أو فساد بالحماية أو الضمانات أو المزايا أو الإعفاءات المقررة بموجب أحكام هذا القانون، ويكون إثبات ذلك كله بموجب حكم قضائي بات صادر من القضاء المختص أو بحكم تحكيم . وفي مجال تطبيق أحكام هذا القانون، تكون جميع القرارات المتعلقة بشئون المشروع الاستثماري مسببة، ويخطر ذوو الشأن بها، وذلك على النحو الذي تنظمه اللائحة التنفيذية لهذا القانون ."}, {"number": "4", "chapter": "الفصل الأول", "text": "لا يجوز تأميم المشروعات الاستثمارية . ولا يجوز نزع ملكية أموال المشروعات الاستثمارية إلا للمنفعة العامة، وبمقابل تعويض عادل يدفع مقدما دون تأخير، وتكون قيمته معادلة للقيمة الاقتصادية العادلة للمال المنزوع ملكيته في اليوم السابق على صدور قرار نزع الملكية، وتكون التعويضات قابلة للتحويل دون قيد . ولا يجوز بالطريق الإداري فرض الحراسة على تلك المشروعات، ولا تفرض الحراسة عليها إلا بموجب حكم قضائي نهائي، كما لا يجوز التحفظ عليها إلا بموجب أمر أو حكم قضائي، ولا يكون ذلك كله إلا في الأحوال المبينة في القانون . ولا يجوز الحجز على أموال المشروعات الاستثمارية أو مصادرتها أو تجميدها إلا بناء على أمر قضائي أو حكم نهائي، وذلك عدا الديون الضريبية، واشتراكات التأمينات الاجتماعية المستحقة للدولة التي يجوز تحصيلها عن طريق الحجز بجميع أنواعه، مع عدم الإخلال بما يتفق عليه في العقود التي تبرمها الدولة أو الأشخاص الاعتبارية العامة مع المستثمر . ولا يجوز لأي جهة إدارية إصدار قرارات تنظيمية عامة تضيف أعباء مالية أو إجرائية، تتعلق بإنشاء أو تشغيل مشروعات تخضع لأحكام هذا القانون أو فرض رسوم أو مقابل خدمات عليها أو تعديلها، إلا بعد أخذ رأي مجلس إدارة الهيئة وموافقة كل من مجلس الوزراء والمجلس الأعلى ."}, {"number": "5", "chapter": "الفصل الأول", "text": "لا يجوز للجهات الإدارية إلغاء التراخيص الصادرة للمشروع الاستثماري أو وقفها أو سحب العقارات التي تم تخصيصها للمشروع إلا بعد إنذار المستثمر بالمخالفات المنسوبة إليه، وسماع وجهة نظره، وإعطائه مهلة مناسبة لإزالة أسباب المخالفة . وفي جميع الأحوال، يجب أخذ رأي الهيئة قبل إصدار القرارات المشار إليها في الفقرة الأولى، وتبدي الهيئة رأيها خلال سبعة أيام من تاريخ ورود الطلب إليها مستوفيا جميع الإجراءات القانونية المقررة . ويحق للمستثمر التظلم من هذا القرار أمام اللجنة المنصوص عليها بالمادة (83) من هذا القانون . وتنظم اللائحة التنفيذية لهذا القانون قواعد تطبيق أحكام هذه المادة وضوابطها ."}, {"number": "6", "chapter": "الفصل الأول", "text": "للمستثمر الحق في إنشاء وإقامة المشروع الاستثماري وتوسيعه، وتمويله من الخارج دون قيود وبالعملة الأجنبية، كما يكون من حقه تملكه، وإدارته، واستخدامه، والتصرف فيه، وجني أرباحه وتحويلها إلى الخارج، وتصفية المشروع، وتحويل ناتج هذه التصفية كله أو بعضه إلى الخارج، وذلك دون الإخلال بحقوق الغير . وتسمح الدولة بإتاحة جميع عمليات التحويل النقدي المتصل بالاستثمار الأجنبي بحرية ودون إبطاء إلى أراضيها وإلى خارجها، بعملة قابلة للتحويل الحر كما تسمح الدولة بتحويل العملة المحلية إلى عملة قابلة للاستخدام بحرية دون تأخير . وفي حالة التصفية تلتزم الجهات الإدارية المختصة بإخطار الهيئة والشركة تحت التصفية ببيان ما عليها من التزامات خلال مدة أقصاها مائة وعشرون يوما تبدأ من تاريخ تقديم المصفي طلبا بذلك مرفقا به المستندات اللازمة ويعتبر انقضاء هذه المدة دون بيان تلك الالتزامات إبراء لذمة الشركة تحت التصفية وذلك دون الإخلال بالمسئولية الجنائية والتأديبية للمسئول عن إصدار بيان على خلاف الواقع أو من تسبب في فوات الميعاد المشار إليه دون الرد على الطلب . وذلك كله وفقا لما تحدده اللائحة التنفيذية لهذا القانون ."}, {"number": "7", "chapter": "الفصل الأول", "text": "مع عدم الإخلال بأحكام القوانين واللوائح والقرارات المنظمة للاستيراد، يحق للمشروعات الاستثمارية الخاضعة لأحكام هذا القانون أن تستورد بذاتها أو عن طريق الغير، ما تحتاج إليه في إنشائها أو التوسع فيها أو تشغيلها من المواد الخام ومستلزمات الإنتاج والآلات وقطع الغيار ووسائل النقل المناسبة لطبيعة نشاطها، دون حاجة لقيدها في سجل المستوردين . كما يحق لهذه المشروعات أن تصدر منتجاتها بالذات أو بالواسطة دون ترخيص وبغير حاجة لقيدها في سجل المصدرين . وتلتزم المشروعات الاستثمارية التي تقوم بالاستيراد أو التصدير وفقا لأحكام هذه المادة سواء بنفسها أو عن طريق الغير بإخطار الهيئة بتقرير ربع سنوي عن الكميات والأنواع المستوردة أو المصدرة بحسب الأحوال ."}, {"number": "8", "chapter": "الفصل الأول", "text": "للمشروع الاستثماري الحق في استخدام عاملين أجانب في حدود نسبة (10%) من إجمالي عدد العاملين بالمشروع، وتجوز زيادة هذه النسبة إلى ما لا يزيد على (20%) من إجمالي عدد العاملين بالمشروع، وذلك في حالة عدم إمكانية استخدام عمالة وطنية تملك المؤهلات اللازمة، وذلك وفقا للضوابط والقواعد التي تبينها اللائحة التنفيذية لهذا القانون . ويجوز في بعض المشروعات الإستراتيجية ذات الأهمية الخاصة التي يصدر بتحديدها قرار من المجلس الأعلى الاستثناء من النسب المشار إليها بشرط مراعاة تدريب العمالة الوطنية . وللعاملين الأجانب في المشروع الاستثماري الحق في تحويل مستحقاتهم المالية كلها أو بعضها إلى الخارج ."}, {"number": "9", "chapter": "الفصل الثاني", "text": "تتمتع جميع المشروعات الاستثمارية الخاضعة لأحكام هذا القانون بالحوافز العامة الواردة في هذا الفصل، وذلك فيما عدا المشروعات المقامة بنظام المناطق الحرة ."}, {"number": "10", "chapter": "الفصل الثاني", "text": "تعفى من ضريبة الدمغة ومن رسوم التوثيق والشهر عقود تأسيس الشركات والمنشآت وعقود التسهيلات الائتمانية والرهن المرتبطة بأعمالها، وذلك لمدة خمس سنوات من تاريخ قيدها في السجل التجاري . كما تعفى من الضريبة والرسوم المشار إليها عقود تسجيل الأراضي اللازمة لإقامة الشركات والمنشآت . وتسري على الشركات والمنشآت الخاضعة لأحكام هذا القانون أحكام المادة (4) من قانون تنظيم الإعفاءات الجمركية الصادر بالقانون رقم 186 لسنة 1986 الخاصة بتحصيل ضريبة جمركية بفئة موحدة مقدارها (2%) اثنان بالمائة من القيمة، وذلك على جميع ما تستورده من آلات ومعدات وأجهزة لازمة لإنشائها . كما تسري هذه الفئة الموحدة على جميع ما تستورده الشركات والمنشآت التي تعمل في مشروعات المرافق العامة، من آلات ومعدات وأجهزة لازمة لإنشائها أو استكمالها . ومع عدم الإخلال بأحكام الإفراج المؤقت المنصوص عليها في قانون الجمارك الصادر بالقانون رقم 66 لسنة 1963، يكون للمشروعات الاستثمارية ذات الطبيعة الصناعية الخاضعة لأحكام هذا القانون استيراد القوالب والأسطمبات وغيرها من مستلزمات الإنتاج ذات الطبيعة المماثلة دون رسوم جمركية وذلك لاستخدامها فترة مؤقتة في تصنيع منتجاتها، وإعادة تصديرها إلى الخارج . ويكون الإفراج والإعادة إلى الخارج بموجب مستندات الوصول، على أن تسجل مستندات الدخول وإعادة الشحن في سجلات تعد لهذا الغرض بالهيئة وذلك بالتنسيق مع وزارة المالية . ثانيا: الحوافز الخاصة"}, {"number": "11", "chapter": "الفصل الثاني", "text": "تمنح المشروعات الاستثمارية التي تقام بعد العمل بهذا القانون وفقا للخريطة الاستثمارية، حافزا استثماريا خصما من صافي الأرباح الخاضعة للضريبة، على النحو الآتي : 1- نسبة (50%) خصما من التكاليف الاستثمارية للقطاع (أ) : ويشمل المناطق الجغرافية الأكثر احتياجا للتنمية طبقا للخريطة الاستثمارية وبناء على البيانات والإحصاءات الصادرة من الجهاز المركزي للتعبئة العامة والإحصاء، ووفقا لتوزيع أنشطة الاستثمار بها على النحو الذي تبينه اللائحة التنفيذية لهذا القانون . 2- نسبة (30%) خصما من التكاليف الاستثمارية للقطاع (ب): ويشمل باقي أنحاء الجمهورية وفقا لتوزيع أنشطة الاستثمار، وذلك للمشروعات الاستثماري الآتية : المشروعات كثيفة الاستخدام للعمالة وفقا للضوابط المنصوص عليها في اللائحة التنفيذية لهذا القانون . المشروعات المتوسطة والصغيرة . المشروعات التي تعتمد على الطاقة الجديدة والمتجددة أو تنتجها . المشروعات القومية والإستراتيجية التي يصدر بتحديدها قرار من المجلس الأعلى . المشروعات السياحية التي يصدر بتحديدها قرار من المجلس الأعلى . مشروعات إنتاج الكهرباء وتوزيعها التي يصدر بتحديدها قرار من رئيس مجلس الوزراء بناء على عرض مشترك من الوزير المختص والوزير المعني بشئون الكهرباء ووزير المالية . المشروعات التي يصدر إنتاجها إلى خارج الإقليم الجغرافي لجمهورية مصر العربية . صناعة السيارات والصناعات المغذية لها . الصناعات الخشبية والأثاث والطباعة والتغليف والصناعات الكيماوية . صناعة المضادات الحيوية وأدوية الأورام ومستحضرات التجميل . الصناعات الغذائية والحاصلات الزراعية وتدوير المخلفات الزراعية . الصناعات الهندسية والمعدنية والنسيجية والجلود . وفي جميع الأحوال يجب ألا يجاوز الحافز الاستثماري (80%) من رأس المال المدفوع حتى تاريخ بدء مزاولة النشاط، وذلك وفقا لأحكام قانون الضريبة على الدخل الصادر بالقانون رقم 91 لسنة 2005 . كما يجب ألا تزيد مدة الخصم على سبع سنوات من تاريخ بدء مزاولة النشاط . ويصدر رئيس مجلس الوزراء قرارا بناء على عرض مشترك من الوزير المختص ووزير المالية والوزير المعني، بتحديد توزيع القطاعات الفرعية لأنشطة الاستثمار بالقطاعين (أ)، و(ب) المشار إليهما . وتبين اللائحة التنفيذية لهذا القانون مفهوم التكلفة الاستثمارية، والنطاق الجغرافي للقطاعين (أ) و(ب)، وشروط منح الحوافز الخاصة وضوابطه، وتدرج بها أنشطة الاستثمار الفرعية التي يتضمنها قرار رئيس مجلس الوزراء المشار إليه فور صدوره . وتجوز إضافة أنشطة جديدة للتمتع بالحوافز الخاصة بقرار من المجلس الأعلى ."}, {"number": "12", "chapter": "الفصل الثاني", "text": "يشترط لتمتع المشروعات الاستثمارية بالحوافز الخاصة المنصوص عليها في المادة (11) من هذا القانون، توافر الشروط الآتية : 1- أن يتم تأسيس شركة أو منشأة جديدة لإقامة المشروع الاستثماري . 2- أن تؤسس الشركة أو المنشأة خلال مدة أقصاها ثلاث سنوات من تاريخ العمل باللائحة التنفيذية لهذا القانون، ويجوز بقرار من مجلس الوزراء وبناء على عرض الوزير المختص مد هذه المدة لمرة واحدة . 3- أن تمسك الشركة أو المنشأة حسابات منتظمة، وإذا كانت الشركة أو المنشأة تعمل في أكثر من منطقة فلها أن تستفيد بالنسبة المقررة لكل منطقة بشرط أن يكون لكل منطقة حسابات مستقلة . 4- ألا يكون أي من المساهمين أو الشركاء أو أصحاب المنشآت قد قدم أو ساهم أو استخدم في إنشاء أو تأسيس أو إقامة المشروع الاستثماري المتمتع بالحافز أيا من الأصول المادية لشركة أو منشأة قائمة وقت العمل بأحكام هذا القانون أو قام بتصفية تلك الشركة أو المنشأة خلال المدة المبينة بالبند (2) من هذه المادة بغرض إنشاء مشروع استثماري جديد يتمتع بالحوافز الخاصة المشار إليها، ويترتب على مخالفة ذلك سقوط التمتع بالحافز المشار إليه والتزام الشركة أو المنشأة بسداد جميع المستحقات الضريبية . ثالثا: الحوافز الإضافية"}, {"number": "13", "chapter": "الفصل الثاني", "text": "مع عدم الإخلال بالحوافز والمزايا والإعفاءات المنصوص عليها في هذا الفصل، يجوز بقرار من مجلس الوزراء منح حوافز إضافية للمشروعات المنصوص عليها في المادة (11) من هذا القانون وذلك على النحو الآتي : 1- السماح بإنشاء منافذ جمركية خاصة لصادرات المشروع الاستثماري أو وارداته بالاتفاق مع وزير المالية . 2- تحمل الدولة قيمة ما يتكلفه المستثمر لتوصيل المرافق إلى العقار المخصص للمشروع الاستثماري أو جزء منها، وذلك بعد تشغيل المشروع . 3- تحمل الدولة لجزء من تكلفة التدريب الفني للعاملين . 4- رد نصف قيمة الأرض المخصصة للمشروعات الصناعية في حالة بدء الإنتاج خلال عامين من تاريخ تسليم الأرض . 5- تخصيص أراض بالمجان لبعض الأنشطة الإستراتيجية وفقا للضوابط المقررة قانونا في هذا الشأن . كما يجوز بقرار من مجلس الوزراء بناء على عرض الوزير المختص استحداث حوافز أخرى غير ضريبية كلما دعت الحاجة إلى ذلك . وتبين اللائحة التنفيذية قواعد منح الحوافز الإضافية المقررة في هذه المادة وضوابطه وشروطه ."}, {"number": "14", "chapter": "الفصل الثاني", "text": "يختص الرئيس التنفيذي للهيئة أو من يفوضه بإصدار الشهادة اللازمة للتمتع بالحوافز المنصوص عليها في المواد (10، 11، 13) للشركات والمنشآت الخاصة لأحكام هذا القانون . وتعتبر هذه الشهادة نهائية ونافذة بذاتها دون حاجة إلى موافقة جهات أخرى ويتعين على جميع الجهات العمل بموجبها والالتزام بما ورد بها من بيانات ."}, {"number": "15", "chapter": "الفصل الثالث", "text": "يجوز للمستثمر تحقيقا لأهداف التنمية الشاملة والمستدامة تخصيص نسبة من أرباحه السنوية لاستخدامها في إنشاء نظام للتنمية المجتمعية، خارج مشروعه الاستثماري، من خلال مشاركته في كل المجالات الآتية أو بعضها : 1- اتخاذ التدابير اللازمة لحماية البيئة وتحسينها . 2- تقديم خدمات أو برامج في مجالات الرعاية الصحية أو الاجتماعية أو الثقافية أو في إحدى مجالات التنمية الأخرى . 3- دعم التعليم الفني أو تمويل البحوث والدراسات وحملات التوعية التي تستهدف تطوير الإنتاج وتحسينه بالاتفاق مع إحدى الجامعات أو مؤسسات البحث العلمي . 4- التدريب والبحث العلمي . ويعد ما ينفقه المستثمر من مبالغ في إحدى المجالات المنصوص عليها في الفقرة السابقة بما لا يجاوز نسبة (10%) من أرباحه السنوية الصافية من التكاليف والمصروفات واجبة الخصم وفقا لنص المادة (23) (بند 8) من قانون الضريبة على الدخل الصادر بالقانون رقم 91 لسنة 2005 ويجوز للوزير المختص بالتنسيق مع الوزارات المعنية إنشاء قائمة لأفضل المشروعات الاستثمارية التي تقوم بأنشطة تنمية مجتمعية سواء من الناحية الجغرافية أو القطاعية أو غيرها ويعلن عنه للرأي العام . وفي جميع الأحوال يحظر استخدام المشروعات أو البرامج أو الخدمات المقدمة بنظام المسئولية المجتمعية لتحقيق أغراض سياسية أو حزبية أو دينية أو تنطوي على تمييز بين المواطنين . وتبين اللائحة التنفيذية للقانون ما يلزم من ضوابط وقواعد أخرى لتطبيق نظام المسئولية المجتمعية ."}, {"number": "16", "chapter": "الفصل الأول", "text": "تقترح الوزارة المختصة الخطة الاستثمارية، وتتضمن هذه الخطة وضع السياسات الاستثمارية موضع التطبيق، وأولويات مشروعات الاستثمار المستهدفة بما يتفق مع السياسة العامة للدولة وخطة التنمية الاقتصادية والاجتماعية، ونظم الاستثمار المطبقة . ويتم إقرارها من المجلس الأعلى . ثانيا: الخريطة الاستثمارية"}, {"number": "17", "chapter": "الفصل الأول", "text": "تتضمن الخطة الاستثمارية وضع خريطة استثمارية تحدد نوعية ونظام الاستثمار . ومناطقه الجغرافية وقطاعاته، كما تحدد العقارات المملوكة للدولة أو للأشخاص الاعتبارية العامة الأخرى المعدة للاستثمار، ونظام التصرف فيها وطريقته بحسب نوع النظام الاستثماري . وتعد الهيئة مشروع الخريطة الاستثمارية بالتنسيق والتعاون الكامل مع جميع أجهزة الدولة المعنية . ويجب مراجعة كل من الخطة والخريطة الاستثمارية مرة على الأقل كل ثلاث سنوات، وكلما دعت الحاجة لذلك بناء على اقتراح الهيئة ."}, {"number": "18", "chapter": "الفصل الأول", "text": "تكون الإجراءات والمدد المنصوص عليها في هذا القانون واجبة التطبيق عند الحصول على خدمات الاستثمار، دون أن يخل ذلك بتطبيق أي قوانين أو إجراءات تتيح للمستثمر الحصول على الموافقات أو التصاريح أو التراخيص بإجراءات أيسر أو خلال مدد زمنية أقل من المنصوص عليها في هذا القانون ولائحته التنفيذية ."}, {"number": "19", "chapter": "الفصل الأول", "text": "تصدر الهيئة خلال تسعين يوما من تاريخ العمل بهذا القانون وبعد التنسيق مع الجهات المختصة، دليلا يتضمن الشروط والإجراءات والمواعيد المقررة لتخصيص العقارات وإصدار الموافقات والتصاريح والتراخيص المتعلقة بالأنشطة الاستثمارية الخاضعة لأحكام هذا القانون، ويتاح هذا الدليل من خلال الموقع الإلكتروني للهيئة ومطبوعاتها المختلفة وغيرها من الجهات . وتلتزم الهيئة بمراجعة هذا الدليل وتحديثه دوريا، وكلما دعت الحاجة إلى ذلك، في ضوء التعديلات التي تطرأ على التشريعات السارية في الدولة . كما تلتزم الجهات المختلفة بموافاة الهيئة خلال ستين يوما على الأكثر من تاريخ العمل بهذا القانون بجميع البيانات والمستندات والنماذج اللازمة لإعداد هذا الدليل . وتحدد اللائحة التنفيذية لهذا القانون الضوابط اللازمة في هذا الشأن ."}, {"number": "20", "chapter": "الفصل الأول", "text": "يجوز بقرار من مجلس الوزراء منح الشركات التي تؤسس لإقامة مشروعات إستراتيجية أو قومية تسهم في تحقيق التنمية أو مشروعات المشاركة بين القطاع الخاص والدولة أو القطاع العام أو قطاع الأعمال العام في أنشطة المرافق العامة والبنية التحتية أو الطاقة الجديدة والمتجددة أو الطرق والمواصلات أو الموانئ، موافقة واحدة على إقامة المشروع وتشغيله وإدارته بما في ذلك تراخيص البناء، وتخصيص العقارات اللازمة له، وتكون هذه الموافقة نافذة بذاتها دون حاجة إلى اتخاذ أي إجراء آخر . كما يجوز أن تتضمن هذه الموافقة سريان أحد الحوافز الواردة بهذا القانون على المشروع أو أكثر، وتبين اللائحة التنفيذية لهذا القانون شروط وإجراءات استخراج هذه الموافقة . ثالثا: مركز خدمة المستثمرين"}, {"number": "21", "chapter": "الفصل الأول", "text": "تنشأ بالهيئة وفروعها، لتبسيط إجراءات الاستثمار وتيسيرها، وحدة إدارية تسمى (مركز خدمات المستثمرين). ويتولى المركز تقديم خدمات تأسيس الشركات وإنشاء فروعها واعتماد محاضر مجالس الإدارة والجمعيات العامة وزيادة رأس المال وتغيير النشاط وأعمال التصفية وغيرها من المسائل المتصلة بالشركات . كما يتولى المركز تلقي طلبات المستثمرين لإصدار الموافقات والتصاريح وتخصيص العقارات والتراخيص اللازمة بأنواعها لإنشاء المشروعات الاستثمارية أو إدارتها، والبت فيها طبقا للقوانين واللوائح خلال المواعيد المنصوص عليها في هذا القانون . وتقدم تدريجيا وفي أسرع وقت ممكن خدمات المركز بطريقة مميكنة وآلية وفقا لما تحدده اللائحة التنفيذية من خلال شبكات الربط الإلكتروني وغيرها من الوسائل الفنية اللازمة . ويضم المركز ممثلين عن الجهات المختصة بحسب القوانين المنظمة، ويخضع ممثلو تلك الجهات لإشراف الهيئة خلال فترة وجودهم بمركز خدمات المستثمرين ويلتزمون بالقواعد والضوابط التي يضعها مجلس إدارة الهيئة لتنظيم عمل المركز . واستثناء من أحكام أي قانون آخر، تنتقل إلى ممثلي الجهات المختصة بموجب أحكام هذا القانون سلطة إصدار الموافقات والتصاريح والتراخيص، بحسب الاشتراطات الفنية الواردة بالقوانين المنظمة لها ودليل إجراءات الاستثمار الذي تصدره الهيئة، وكذا جميع الصلاحيات المقررة للسلطة المختصة في مجال تخصيص العقارات وإعطاء الموافقات والتصاريح والتراخيص اللازمة لعمل المستثمر والاستثمار وفقا لأحكام هذا القانون . ويحدد مجلس إدارة الهيئة الجهات الحكومية وشركات المرافق العامة التي يتكون منها مركز خدمات المستثمرين، ويقوم الرئيس التنفيذي للهيئة بالتنسيق مع تلك الجهات لتحديد العدد اللازم من العاملين الأصليين والاحتياطيين لتمثيلها في المركز ودرجاتهم الوظيفية التي تسمح لهم بأداء واجباتهم في مركز خدمات المستثمرين، كما تحدد اللائحة التنفيذية ضوابط اختيار هؤلاء العاملين وطريقة إلحاقهم بالمركز . وفي غير حالات تقديم شهادات الاعتماد المنصوص عليها في المواد التالية، يجب على ممثلي الجهات بمركز خدمات المستثمرين والموظفين المسئولين بالجهات الإدارية طلب استيفاء المستندات اللازمة لاستخراج الموافقات أو التصاريح أو التراخيص خلال يومي عمل من تاريخ تقديمها إليهم، وإلا اعتبرت مستوفاة، ولا يجوز طلب أي مستندات إضافية من المستثمر بعد مرور تلك المدة . وفي جميع الأحوال، يكون من حق المستثمر أن يقوم باستيفاء الاشتراطات الفنية وغيرها من الاشتراطات والإجراءات اللازمة للاستثمار عن طريق مكاتب الاعتماد، أو باللجوء مباشرة إلى الجهات المختصة، أو من خلال ممثليها بمركز خدمات المستثمرين . رابعا: مكاتب الاعتماد"}, {"number": "22", "chapter": "الفصل الأول", "text": "يجوز لطالب الاستثمار أو من ينوب عنه، أن يعهد إلى مكاتب الاعتماد المرخص لها من الهيئة بفحص المستندات الخاصة بالحصول على الموافقات والتصاريح والتراخيص اللازمة لإنشاء المشروع الاستثماري وتشغيله والتوسع فيه، لتحديد مدى استيفائه الاشتراطات الفنية والمالية اللازمة وغيرها من الإجراءات المنصوص عليها في أحكام هذا القانون والقوانين المنظمة لمنح الموافقات والتصاريح والتراخيص . وتلتزم مكاتب الاعتماد في ممارسة عملها بقواعد المسئولية المهنية التي تحددها اللائحة التنفيذية، وعلى الأخص القواعد الآتية : الالتزام بأحكام القوانين والقرارات ذات الصلة . بذل العناية الواجبة في الفحص والاستيفاء والاعتماد . تجنب تعارض المصالح . الحفاظ على سرية وخصوصية المعلومات المتعلقة بطالبي الاعتماد . ويجوز أن تعمل مكاتب الاعتماد منفردة أو بالاشتراك مع مجموعة من مكاتب الاعتماد المتخصصة . وتحدد اللائحة التنفيذية لهذا القانون الشكل القانوني لمكاتب الاعتماد . ويصدر الترخيص لمكاتب الاعتماد التي يتوافر لديها الخبرة اللازمة لممارسة هذا النشاط وفقاً للشروط والقواعد والإجراءات التي تحددها اللائحة التنفيذية لهذا القانون بما في ذلك الالتزام بإبرام وثيقة تأمين سنوية لتغطية المخاطر والأضرار الناتجة عما تقوم به هذه المكاتب من أنشطة وأسس تحديد مقابل الخدمات التي تقوم بتقديمها . وينشأ بالهيئة سجل خاص تقيد فيه مكاتب الاعتماد المرخص لها توافي به الجهات الإدارية المختصة . ويكون الترخيص لمكاتب الاعتماد مقابل رسم لا يجاوز عشرين ألف جنيه تحدد فئاته اللائحة التنفيذية، ويجدد الترخيص سنوياً، ويسري على تجديد الترخيص ذات الرسوم المقررة لمنح التراخيص . وتصدر مكاتب الاعتماد للمستثمر وعلى مسئوليتها شهادة اعتماد صالحة لمدة عام، تتضمن بيان مدى استيفاء المشروع الاستثماري كل شروطه أو بعضها طبقاً للقوانين واللوائح المنظمة لإصدار الموافقات والتصاريح والتراخيص، على أن تقوم بإرسال نسخة إلى الجهة المختصة بالطريقة التي تبينها اللائحة التنفيذية لهذا القانون. ولا يعتد بالشهادات التي تقدم بعد مضي عام من تاريخ صدورها . وتكون هذه الشهادة مقبولة لدى الجهة المختصة وممثلها بمركز خدمات المستثمرين وغيرها من الجهات الإدارية، ولا يحول ذلك دون إبداء الجهة المختصة أو ممثلها اعتراضاً مسبباً على الشهادة المشار إليها، في موعد غايته عشرة أيام عمل من تاريخ تقديمها، وفي حالة انقضاء هذه المدة دون رد، اعتبر ذلك قبولاً لطلب المستثمر يصدر به موافقة من الرئيس التنفيذي للهيئة، وذلك على النحو المنصوص عليه في المادة (25) من هذا القانون . وتعتبر هذه الشهادة محرراً رسمياً في تطبيق أحكام قانون العقوبات . ومع عدم الإخلال بالمسئولية المدنية أو الجنائية بحسب الأحوال، يترتب على إصدار هذه الشهادة على خلاف الحقيقة أو بالمخالفة للقواعد المنصوص عليها في المادة (25) من هذا القانون، استحقاق قيمة التأمين وصرفها للمستفيدين منها، وشطب المكتب الصادرة عنه من سجل القيد لدى الهيئة مدة لا تجاوز ثلاث سنوات بقرار من مجلس إدارة الهيئة، وفي حالة تكرار ارتكاب المخالفة يكون الشطب نهائياً من السجل . وذلك كله على النحو الذي تبينه اللائحة التنفيذية لهذا القانون ."}, {"number": "23", "chapter": "الفصل الأول", "text": "يؤدي المستثمر للهيئة جميع الرسوم وغيرها من المبالغ التي تفرضها القوانين، لحساب الجهات التي تقدم خدمات الاستثمار . وتستحق الهيئة مقابلاً لما تؤديه للمستثمرين من خدمات فعلية، ويصدر مجلس إدارة الهيئة قراراً بتحديد فئات هذا المقابل والقواعد والشروط والإجراءات المنظمة لتحصيله ."}, {"number": "24", "chapter": "الفصل الأول", "text": "مع عدم الإخلال بالمدد المقررة للبت في الطلب المرفق به شهادة من أحد مكاتب الاعتماد، تتولى الجهات المختصة فحص طلبات الاستثمار التي تقدم إليها من خلال مركز خدمات المستثمرين، والتأكد من مدى توافر الشروط اللازمة لقبولها على النحو المبين في هذا القانون، ويجب البت فيها خلال مدة لا تجاوز ستين يوماً من تاريخ تقديم الطلب مستوفياً جميع مستنداته، وفي حالة انقضاء هذه المدة دون قرار منها، اعتبر ذلك قبولاً لطلب المستثمر يصدر به موافقة من الرئيس التنفيذي للهيئة وذلك على النحو المنصوص عليه في المادة (25) من هذا القانون . وفي جميع الأحوال، يجب إخطار مقدم الطلب بالقرار الصادر في طلبه سواء بالموافقة أو الرفض، بموجب خطاب مسجل بعلم الوصول، خلال سبعة أيام من تاريخ انقضاء المدة المنصوص عليها في الفقرة الأولى من هذه المادة . ولذوي الشأن التظلم من قرار الرفض أمام اللجنة المنصوص عليها في المادة (83) من هذا القانون ."}, {"number": "25", "chapter": "الفصل الأول", "text": "يتولى الرئيس التنفيذي للهيئة إصدار الموافقات المنصوص عليها في المادتين (22، 24) من هذا القانون على النموذجين المعدين لهذا الغرض، وذلك على النحو الذي تبينه اللائحة التنفيذية لهذا القانون ."}, {"number": "26", "chapter": "الفصل الأول", "text": "في إطار خطة التنمية الاقتصادية للدولة أو لأغراض استكمال الخريطة الاستثمارية، يجوز للهيئة استخراج الموافقات أو التصاريح أو التراخيص اللازمة لإقامة النشاط على قطع الأراضي المخصصة للاستثمار قبل تخصيصها للمستثمرين، وفي هذه الحالة تحصل قيمة الرسوم وغيرها من الأعباء المالية المستحقة لحساب الجهات المختصة نظير هذه الموافقات أو التصاريح أو التراخيص من المستثمر عند إتمام إجراءات تخصيص الأرض، ويتعين على هذه الجهات الالتزام بتيسير إجراءات منح تلك الموافقات أو التصاريح أو التراخيص وفقاً للإجراءات والمواعيد التي تحددها اللائحة التنفيذية لهذا القانون ."}, {"number": "27", "chapter": "الفصل الأول", "text": "يلتزم العاملون القائمون على تنفيذ أحكام هذا القانون، في جميع الجهات المختصة ذات الصلة، بمراعاة الأهداف والمبادئ والإجراءات والمواعيد الواردة به وبلائحته التنفيذية . ويكون تيسير الإجراءات على المستثمرين وسرعة وإنجاز مصالحهم المشروعة، من المؤشرات الأساسية لقياس أداء هؤلاء العاملين وأحد سبل تحديد مسئوليتهم الوظيفية ."}, {"number": "28", "chapter": "الفصل الثاني", "text": "يجوز بقرار من رئيس مجلس الوزراء بناءً على اقتراح مجلس إدارة الهيئة وعرض الوزير المختص والوزير المعني إنشاء مناطق استثمارية متخصصة في مختلف مجالات الاستثمار بما فيها المناطق اللوجيستية والزراعية والصناعية، على أن يتضمن قرار إنشاء المنطقة موقعها وإحداثياتها، وطبيعة الأنشطة التي تزاول فيها، والمدة التي يجب اتخاذ الإجراءات اللازمة لإنشاء المنطقة خلالها، بالإضافة إلى أي شروط عامة ترتبط بمزاولة تلك الأنشطة . وعلى المطور الذي يتولى أمر المنطقة الاستثمارية اتخاذ الإجراءات اللازمة نحو إنشائها وفقاً للبرنامج الزمني للتنفيذ المحدد بالترخيص وإلا اعتبر الترخيص كأن لم يكن . ويجوز بقرار من رئيس مجلس الوزراء أو من يفوضه منح المرخص له مهلة إضافية في ضوء المبررات المقدمة منه بعد موافقة مجلس إدارة الهيئة . وتسري على المشروعات العاملة داخل المناطق الاستثمارية، أحكام البابين الأول والثاني من هذا القانون، وذلك فيما لا يتعارض مع طبيعة العمل بأحكام هذا النظام . كما تسري عليها القواعد الخاصة بالسماح الجمركي المؤقت والدروباك الواردة بالقوانين واللوائح والقرارات المنظمة لذلك . وتجوز إضافة أنشطة أخرى بقرار من رئيس مجلس الوزراء بناءً على عرض الوزير المختص ."}, {"number": "29", "chapter": "الفصل الثاني", "text": "يكون لكل منطقة استثمارية مجلس إدارة، يصدر بتشكيله قرار من الوزير المختص بالاتفاق مع الوزير المعني بحسب نوع وتخصص المنطقة . ويختص مجلس إدارة المنطقة بوضع خطة عمل المنطقة والضوابط والمعايير اللازمة لممارسة النشاط، واعتمادها من مجلس إدارة الهيئة، كما يختص بالموافقة على إقامة المشروعات الاستثمارية داخل حدود المنطقة، كما يلتزم مجلس الإدارة بتقديم تقارير ربع سنوية إلى الهيئة وفقاً لما تحدده اللائحة التنفيذية، ويرسل محاضر اجتماعات مجلس الإدارة لاعتمادها من الهيئة . ولمجلس إدارة المنطقة أن يرخص لشركات من القطاع الخاص بتنمية تلك المناطق وإدارتها أو الترويج للاستثمار بها . ويلتزم أعضاء مجلس الإدارة بالإفصاح عن جميع أموالهم، على أن يتم تقديم هذا الإفصاح ومراجعته سنوياً من جهة مستقلة للتحقق من عدم وجود مخالفة أو تضارب فعلي أو محتمل للمصالح، على أن يرفع بذلك تقرير إلى المجلس الأعلى عن طريق الوزير المختص ."}, {"number": "30", "chapter": "الفصل الثاني", "text": "يكون للمنطقة الاستثمارية مكتب تنفيذي من العاملين بالهيئة يصدر بهم قرار من الرئيس التنفيذي للهيئة باعتماد من الوزير المختص، ويتولى المكتب تنفيذ قرارات مجلس إدارة المنطقة فيما يخص الموافقات والتصاريح والتراخيص اللازمة ومتابعة تنفيذها، وإصدار تراخيص البناء للمشروعات داخل حدود المنطقة . ويؤدي المستثمر للهيئة مقابلاً عن كل خدمة فعلية يقدمها المكتب التنفيذي بما لا يجاوز واحداً في الألف من التكاليف الاستثمارية عن جميع الخدمات المقدمة، وذلك على النحو الذي تحدده اللائحة التنفيذية لهذا القانون ."}, {"number": "31", "chapter": "الفصل الثاني", "text": "يختص رئيس مجلس إدارة المنطقة، فضلا عما هو منوط به، بالترخيص للمشروعات داخل حدود المنطقة الاستثمارية بمزاولة نشاطها . ويجب أن يتضمن الترخيص بيانا بالأغراض التي منح من أجلها ومدة سريانه، ولا يجوز النزول عن الترخيص كليا أو جزئيا إلا بموافقة مجلس إدارة المنطقة الاستثمارية، ويكون رفض منح الترخيص أو عدم الموافقة على النزول عنه بقرار مسبب، ولصاحب الشأن أن يتظلم منه إلى اللجنة المنصوص عليها بالمادة (83) من هذا القانون . ويكتفي بهذا الترخيص عند التعامل مع أجهزة الدولة المختلفة للحصول على الخدمات والتيسيرات والمزايا والإعفاءات للمشروع دون حاجة للقيد بالسجل الصناعي، ما لم يطلب المستثمر غير ذلك، مع إخطار الجهة المختصة بصورة من الترخيص لأغراض الحصر، ولا يجوز لأي جهة إدارية أخرى اتخاذ أي إجراءات داخل المناطق الاستثمارية أو المشروعات العاملة داخلها إلا بعد موافقة الهيئة . ولا يتمتع المرخص له بالضمانات والحوافز والمزايا المنصوص عليها في هذا القانون إلا في حدود الأغراض المبينة في الترخيص ."}, {"number": "32", "chapter": "الفصل الثالث", "text": "لرئيس مجلس الوزراء بناء على اقتراح مجلس إدارة الهيئة وبطلب من الوزير المعني بشئون الاتصالات وتكنولوجيات المعلومات، الترخيص بإنشاء مناطق تكنولوجية، في مجال صناعة تكنولوجيا المعلومات والاتصالات، بما تشمله من أنشطة صناعية وتصميم وتطوير الإلكترونيات، ومراكز البيانات، وأنشطة التعهيد، وتطوير البرمجيات، والتعليم التكنولوجي، وغيرها من الأنشطة المرتبطة بها أو المكملة لها، وذلك كله وفقا لما تبينه اللائحة التنفيذية لهذا القانون . وتجوز إضافة أنشطة أخرى بقرار من رئيس مجلس الوزراء بناء على عرض مشترك من الوزير المختص والوزير المعني بشئون الاتصالات وتكنولوجيا المعلومات . ولا تخضع جميع الأدوات والمهمات والآلات اللازمة لمزاولة النشاط المرخص به للمشروعات المتواجدة داخل المناطق التكنولوجية بجميع أنواعها للضرائب والرسوم الجمركية، وفقا للشروط والإجراءات التي تبينها اللائحة التنفيذية . وتتمتع المشروعات المقامة في المناطق التكنولوجية بالحوافز الخاصة المنصوص عليها في المادة (11) من هذا القانون بحسب القطاع المقامة به . ويكون لكل منطقة مجلس إدارة يصدر بتشكيله قرار من الوزير المختص بشئون الاتصالات وتكنولوجيا المعلومات بالاتفاق مع الوزير المختص، ويختص مجلس إدارة المنطقة بوضع الضوابط والمعايير اللازمة لممارسة النشاط، كما يختص بالموافقة على إقامة المشروعات داخل حدود المنطقة . ويلتزم أعضاء مجلس الإدارة بالإفصاح عن جميع أموالهم، على أن يتم تقديم هذا الإفصاح ومراجعته سنويا من جهة مستقلة للتحقق من عدم وجود مخالفة أو تضارب فعلي أو محتمل للمصالح، على أن يرفع بذلك تقرير إلى المجلس الأعلى عن طريق الوزير المختص . وتسري على الاستثمار بنظام المناطق التكنولوجية أحكام البابين الأول والثاني من هذا القانون فيما لا يتعارض مع طبيعة العمل بهذا النظام . وتبين اللائحة التنفيذية لهذا القانون اشتراطات وضوابط العمل فيها وأسلوب إدارتها ."}, {"number": "33", "chapter": "الفصل الرابع", "text": "يكون إنشاء المنطقة الحرة التي تشمل مدينة بأكملها بقانون . ولمجلس الوزراء بناء على عرض الوزير المختص بعد موافقة مجلس إدارة الهيئة، إنشاء مناطق حرة عامة لإقامة المشروعات التي يرخص بها، أيا كان شكلها القانوني، تهدف بالأساس إلى التصدير خارج البلاد، ويجب أن يتضمن القرار الصادر بإنشاء المنطقة الحرة بيانا بموقعها وحدودها . ويتولى إدارة المنطقة الحرة العامة مجلس إدارة يصدر بتشكيله وتعيين رئيسه قرار من الرئيس التنفيذي للهيئة باعتماد من الوزير المختص، ويقوم أعضاء مجلس الإدارة بالإفصاح عن جميع أموالهم، على أن يقدم ويراجع هذا الإفصاح سنويا من قبل جهة مستقلة للتحقق من عدم وجود مخالفة أو تضارب فعلي أو محتمل للمصالح، على أن يرفع بذلك تقرير إلى المجلس الأعلى عن طريق الوزير المختص . ويختص مجلس إدارة المنطقة الحرة العامة على الأخص باقتراح اللوائح والنظم اللازمة لإدارة المنطقة الحرة، واعتمادها من مجلس إدارة الهيئة، وتنفيذ أحكام هذا القانون ولائحته التنفيذية والقرارات التي تصدرها الهيئة . كما يجوز لمجلس الوزراء بناء على عرض الوزير المختص الموافقة على إنشاء مناطق حرة خاصة تقتصر كل منها على مشروع أو أكثر في أنشطة مماثلة متى اقتضت طبيعتها ذلك، وتنظم اللائحة التنفيذية سائر أوضاع العمل بالمناطق الحرة الخاصة بما يضمن حسن قيامها بأعمالها وحوكمتها ."}, {"number": "34", "chapter": "الفصل الرابع", "text": "مع عدم الإخلال بأحكام القانون رقم 133 لسنة 2010 بالترخيص لمشروعات تكرير البترول بالعمل بنظام المناطق الحرة، ومع مراعاة المراكز القانونية للشركات المرخص لها بإقامة مشروعات بنظام المناطق الحرة القائمة وقت العمل بهذا القانون، لا يجوز الترخيص بإقامة مشروعات بنظام المناطق الحرة في مجال تصنيع البترول، وصناعات الأسمدة، والحديد والصلب، وتصنيع وتسييل ونقل الغاز الطبيعي والصناعات كثيفة استخدام الطاقة التي يصدر بتحديدها قرار من المجلس الأعلى للطاقة، وصناعات الخمور والمواد الكحولية، وصناعات الأسلحة والذخائر والمتفجرات وغيرها مما يرتبط بالأمن القومي ."}, {"number": "35", "chapter": "الفصل الرابع", "text": "مع عدم الإخلال بنص الفقرة الأولى من المادة (10) من هذا القانون، تخضع جميع المشروعات التي تستثمر بنظام المناطق الحرة للرقابة الجمركية والضريبية وفقا للقواعد التي يصدر بها قرار من مجلس إدارة الهيئة بالتنسيق مع مصلحتي الجمارك والضرائب المصرية . ويلتزم مجلس إدارة المنطقة الحرة بإخطار الجهات التي يحددها الوزير المعني بشئون الصناعة بجميع البيانات المتعلقة بالمشروعات الإنتاجية الصناعية التي تقام بالمناطق الحرة، ويكون للوزير المختص بالاتفاق مع الوزير المعني بشئون الصناعة وضع ضوابط مباشرة المشروعات الإنتاجية الصناعية لأنشطتها، وعلى الأخص ما تلتزم به هذه المشروعات من نسب تصديرية ."}, {"number": "36", "chapter": "الفصل الرابع", "text": "مع مراعاة أحكام قانون سوق رأس المال الصادر بالقانون رقم 95 لسنة 1992، وقانون البنك المركزي والجهاز المصرفي والنقد الصادر بالقانون رقم 88 لسنة 2003، والقانون رقم 10 لسنة 2009 بتنظيم الرقابة على الأسواق والأدوات المالية غير المصرفية، يختص مجلس إدارة المنطقة الحرة العامة بالموافقة النهائية على إقامة المشروعات داخل المنطقة، أو في المنطقة الحرة الخاصة التي تقع في نطاقها الجغرافي، ويختص رئيس مجلس إدارة المنطقة بالترخيص لها بمزاولة نشاطها . ويجب أن يتضمن الترخيص بيانا بالأغراض التي منح من أجلها ومدة سريانه ومقدار ونوع الضمان المالي الذي يؤديه المرخص له بما لا يجاوز اثنان بالمائة (2%) من التكاليف الاستثمارية وفقا للنسب التي تبينها اللائحة التنفيذية لهذا القانون، ولا يجوز النزول عن الترخيص كليا أو جزئيا، إلا بموافقة مجلس إدارة المنطقة . ولا يتمتع المشروع المرخص له بالإعفاءات أو المزايا المنصوص عليها في هذا القانون إلا في حدود الأغراض المبينة في الترخيص، ويكتفي بهذا الترخيص عند التعامل مع أجهزة الدولة المختلفة، للحصول على الخدمات والتيسيرات والمزايا للمشروع، دون حاجة للقيد بالسجل الصناعي، ما لم يتطلب المشروع ذلك، مع إخطار الجهة المختصة بصورة من هذا الترخيص لأغراض الحصر والإحصاء ."}, {"number": "37", "chapter": "الفصل الرابع", "text": "يكون تخصيص العقارات اللازمة لإقامة المشروعات للعمل بنظام المناطق الحرة العامة بنظام الترخيص بالانتفاع وفقا للقواعد والأحكام التي تبينها اللائحة التنفيذية لهذا القانون . وعلى المستثمر التقدم لإدارة المنطقة خلال ثلاثين يوما من تاريخ إبلاغه بالموافقة على إقامة مشروعه لاستلام الأرض لتنفيذ المشروع والتوقيع على عقد الانتفاع وسداد القيمة المقررة . وتسقط الموافقة على المشروع إذا لم يقم المستثمر باتخاذ إجراءات جدية في تنفيذ المشروع خلال تسعين يوما من تاريخ إخطاره باستلام الأرض وفقا للشروط المتفق عليها في عقد الانتفاع، ويجوز مد هذه الفترة لمدة أخرى في ضوء المبررات التي يقدمها المستثمر أو من يمثله ويقدرها مجلس إدارة المنطقة الحرة . وتبين اللائحة التنفيذية لهذا القانون الضوابط والإجراءات اللازمة لتنفيذ هذه الأحكام ."}, {"number": "38", "chapter": "الفصل الرابع", "text": "يلتزم المستثمر بتسليم الأرض المخصصة له إلى إدارة المنطقة عند إلغاء المشروع أو سقوط الموافقة الصادرة له خالية من الإشغالات، وفي حالة وجود مبان أو منشآت أو موجودات بالموقع يلتزم بإخلائها على نفقته الخاصة خلال المدة التي يحددها مجلس إدارة المنطقة بما لا يجاوز ستة أشهر من تاريخ إخطاره بذلك بخطاب مسجل بعلم الوصول . فإذا لم يقم بالإخلاء خلال هذه المدة، يصدر مجلس إدارة المنطقة قرارا باسترداد الأرض بالطريق الإداري بما عليها من مبان وإنشاءات، وتقوم إدارة المنطقة والجمارك في حالة وجود موجودات بالموقع بجردها وحصرها وتسليمها إلى إدارة الجمارك للاحتفاظ بها مؤقتا أو بيعها وفقا لأحكام قانون الجمارك بشأن المهمل أو المتروك وإيداع ثمنها في حساب لدى الهيئة لصالح المستثمر، بعد خصم مستحقات الهيئة ثم الديون الحكومية، وذلك على النحو الذي تبينه اللائحة التنفيذية لهذا القانون . وتعتبر مستحقات الهيئة في تطبيق أحكام هذه المادة من الديون الممتازة التالية للمصروفات القضائية ومستحقات الخزانة العامة ."}, {"number": "39", "chapter": "الفصل الرابع", "text": "مع مراعاة الأحكام التي تقررها القوانين واللوائح بشأن منع تداول بعض البضائع والمواد، لا تخضع البضائع التي تصدرها مشروعات المنطقة الحرة إلى خارج البلاد أو تستوردها من خارج البلاد لمزاولة نشاطها للقواعد الخاصة بالاستيراد والتصدير ولا للإجراءات الجمركية الخاصة بالصادرات والواردات، كما لا تخضع للضرائب الجمركية والضريبة على القيمة المضافة وغيرها من الضرائب والرسوم . ويكون تصدير مستلزمات الإنتاج من السوق المحلي إلى المشروعات الإنتاجية بالمناطق الحرة وفقا للقواعد التي يصدر بها قرار من الوزير المعني بشئون التجارة الخارجية بالاتفاق مع الوزير المختص ووزير المالية . وفيما عدا سيارات الركوب، تعفى من الضرائب الجمركية والضريبة على القيمة المضافة وغيرها من الضرائب والرسوم؛ جميع الأدوات والمهمات والآلات ووسائل النقل الضرورية بجميع أنواعها واللازمة لمزاولة النشاط المرخص به للمشروعات الموجودة داخل المناطق الحرة بجميع أنواعها ولو اقتضت طبيعة مزاولة هذا النشاط وضروراتها خروجها مؤقتا من المنطقة الحرة إلى داخل البلاد وإعادتها إليها وذلك بالنسبة إلى الأدوات والمهمات والآلات وفي الحالات وبالضمانات والشروط والإجراءات التي يصدر بها قرار من مجلس الوزراء بناء على عرض الوزير المختص ووزير المالية . وتبين اللائحة التنفيذية لهذا القانون إجراءات نقل البضائع وتأمينها من بدء تفريغها حتى وصولها إلى المناطق الحرة وبالعكس . وللهيئة السماح بإدخال البضائع والمواد والأجزاء والخامات المحلية والأجنبية، المملوكة للمشروع أو للغير، من داخل البلاد إلى المنطقة الحرة مؤقتا لإصلاحها أو لإجراء عمليات صناعية عليها وإعادتها لداخل البلاد دون خضوعها لقواعد الاستيراد المطبقة، وذلك على النحو الذي تبينه اللائحة التنفيذية لهذا القانون . وتحصل الضريبة الجمركية على قيمة الإصلاح وفقا لأحكام القوانين الجمركية ."}, {"number": "40", "chapter": "الفصل الرابع", "text": "يكون الاستيراد من المناطق الحرة إلى داخل البلاد طبقا للقواعد العامة للاستيراد من الخارج . واستثناء من ذلك، يسمح بدخول المواد والنفايات والمخلفات الناتجة عن أنشطة المشروعات العاملة بالمناطق الحرة إلى داخل البلاد متى كان دخولها إلى البلاد بغرض التخلص منها أو إعادة تدويرها، وذلك بالطرق والوسائل الآمنة المقررة وفقا لقانون البيئة الصادر بالقانون رقم 4 لسنة 1994، على نفقة صاحب الشأن . وتطبق أحكام قانون البيئة المشار إليه في شأن حظر استيراد النفايات الخطرة من الخارج . وتؤدي الضرائب الجمركية على البضائع التي تستورد من المنطقة الحرة إلى السوق المحلي كما لو كانت مستوردة من خارج البلاد . أما المنتجات المستوردة من مشروعات المناطق الحرة والتي تشتمل على مكونات محلية وأخرى أجنبية، فيكون وعاء الضريبة الجمركية بالنسبة لها هو قيمة المكونات الأجنبية بالسعر السائد وقت خروجها من المنطقة الحرة إلى داخل البلاد، بشرط ألا تزيد الضريبة الجمركية المستحقة على المكونات الأجنبية على الضريبة المستحقة على المنتج النهائي المستورد من الخارج . وتتمثل المكونات الأجنبية في الأجزاء والمواد الأجنبية المستوردة حسب حالتها عند الدخول إلى المنطقة الحرة دون حساب تكاليف التشغيل بتلك المنطقة وتعتبر المنطقة الحرة فيما يتعلق بحساب النولون بلد المنشأ بالنسبة للمنتجات المصنعة فيها ."}, {"number": "41", "chapter": "الفصل الرابع", "text": "لا تخضع المشروعات داخل المناطق الحرة والأرباح التي توزعها لأحكام قوانين الضرائب والرسوم السارية في مصر . ومع ذلك تخضع هذه المشروعات للمعاملة الآتية : أولا - تخضع المشروعات في المناطق الحرة العامة: 1- لرسم مقداره اثنان بالمائة (2%) من قيمة السلع عند الدخول (سيف) بالنسبة لمشروعات التخزين ولرسم مقداره واحد بالمائة (1%) من قيمة السلع عند الخروج (فوب) بالنسبة لمشروعات التصنيع والتجميع، وتعفى من الرسم تجارة البضائع العابرة (ترانزيت) المحددة الوجهة . 2- لرسم مقداره واحد بالمائة (1%) من إجمالي الإيرادات التي تحققها بالنسبة للمشروعات التي لا يقتضي نشاطها الرئيسي إدخال سلع أو إخراجها، وذلك من واقع القوائم المالية المعتمدة من أحد المحاسبين القانونيين . ثانيا - تخضع المشروعات في المناطق الحرة الخاصة: 1- لرسم مقداره واحد بالمائة (1%) من إجمالي الإيرادات التي تحققها بالنسبة لمشروعات التصنيع والتجميع عند تصدير السلع إلى خارج البلاد، واثنان بالمائة (2%) من إجمالي إيرادات هذه المشروعات عند دخول السلع إلى البلاد، وتعفى من الرسوم تجارة البضائع العابرة (ترانزيت) المحددة الوجهة . 2- لرسم مقداره اثنان بالمائة (2%) من إجمالي الإيرادات التي تحققها؛ وذلك فيما يتعلق بغير ذلك من المشروعات الواردة بالبند السابق . وتؤول حصيلة الرسوم الواردة بالبند (أولا) من هذه المادة إلى الهيئة، وتوزع حصيلة الرسوم الواردة بالبند (ثانيا) من هذه المادة مناصفة بين وزارة المالية والهيئة . وفي جميع الأحوال تلتزم المشروعات المقامة في المناطق الحرة العامة والخاصة بأداء مقابل سنوي للخدمات للهيئة لا يجاوز مقداره (واحدا في الألف) (001.%) من رأس المال بحد أقصى مائة ألف جنيه وفقا للنسب التي تبينها اللائحة التنفيذية لهذا القانون، ويجوز أداء ما يعادل قيمتها بالعملة التي يحددها الوزير المختص . كما تلتزم هذه المشروعات بتقديم القوائم المالية معتمدة من أحد المحاسبين القانونيين إلى كل من وزارتي المالية والاستثمار ."}, {"number": "42", "chapter": "الفصل الرابع", "text": "تعفى مشروعات النقل البحري التي تنشأ في المناطق الحرة من الشروط الخاصة بجنسية مالك السفينة والعاملين عليها المنصوص عليها في القانون رقم 84 لسنة 1949 بشأن تسجيل السفن التجارية، وقانون التجارة البحرية الصادرة بالقانون رقم 8 لسنة 1990 . كما تستثنى السفن المملوكة لهذه المشروعات من أحكام القانون رقم 12 لسنة 1964 بإنشاء المؤسسة المصرية العامة للنقل البحري ."}, {"number": "43", "chapter": "الفصل الرابع", "text": "يلتزم المستثمر بالتأمين الشامل على المباني والآلات والمعدات ضد جميع الحوادث والمخاطر التي تنشأ من مزاولة النشاط المرخص به . ولمجلس إدارة المنطقة إصدار قرار بإزالة منشآت المشروع في حالة وقوع الحادث أو الخطر المؤمن ضده، ويجب أن يكون القرار مسببا ويعلن به المستثمر أو من يمثله خلال أسبوع من تاريخ صدوره بموجب خطاب مسجل مصحوبا بعلم الوصول، ويجوز لإدارة المنطقة تقصير هذا الميعاد للضرورة . وعلى المستثمر تنفيذ قرار الإزالة على نفقته وخلال الموعد الذي تحدده إدارة المنطقة . ويكون لمجلس إدارة المنطقة في حالة امتناع المستثمر عن التنفيذ وقف نشاط المشروع أو إلغاؤه، بحسب جسامة المخالفة ."}, {"number": "44", "chapter": "الفصل الرابع", "text": "في جميع الأحوال التي ترد فيها الرسائل من الخارج ويفرج عنها من الجمارك برسم المناطق الحرة، يتم معاينتها بواسطة لجنة ثلاثية من المنطقة والجمرك المختص وصاحب الشأن أو من ينيبه داخل مقر المشروع، ويحرر بيان بتوقيعهم موضحا به نتيجة المعاينة بعد المطابقة على الفواتير أو بيان العبوة، وتسلم الرسالة إلى صاحب الشأن وتصبح في عهدته وتحت مسئوليته الكاملة، وتلتزم مصلحة الجمارك بتقدير قيمة هذه الرسالة وإبلاغ إدارة المنطقة بها . وعلى مدير جمرك المنطقة إخطار رئيس المنطقة بحالات النقص أو الزيادة غير المبررة عما أدرج في قائمة الشحن سواء في عدد الطرود أو محتوياتها أو البضائع المحفوظة أو المنفرطة (الصب) . ويصدر بتنظيم المسئولية عن الحالات المنصوص عليها في الفقرة السابقة وبنسب التسامح فيها، قرار من مجلس إدارة الهيئة ."}, {"number": "45", "chapter": "الفصل الرابع", "text": "لا تخضع المشروعات في المناطق الحرة لأحكام القانون رقم 113 لسنة 1958 بشأن التعيين في وظائف شركات المساهمة والمؤسسات العامة . وتطبق أحكام قانون العمل على علاقات العمل والسلامة والصحة المهنية بهذه المناطق، وتعد هذه الأحكام فيما تضمنته من حقوق للعمال حدا أدنى لما يجوز الاتفاق عليه في عقود العمل الفردية أو الجماعية، التي تبرم مع العاملين في المشروعات المرخص لها بالعمل في هذه المناطق . وتضع المشروعات في المناطق الحرة لائحة داخلية بنظام العمل بها تكون ملزمة لها، وتقدمها للرئيس التنفيذي للهيئة أو من يفوضه للتصديق عليها، وتكون هذه اللائحة مكملة لعقود العمل الفردية أو الجماعية . وللرئيس التنفيذي للهيئة الاعتراض على ما تضمنته اللائحة الداخلية من أحكام تخالف النظام العام أو إذا تضمنت مزايا أقل من المقررة في قانون العمل . وتسري أحكام قانون التأمين الاجتماعي الصادر بالقانون رقم 79 لسنة 1975 على العاملين بالمشروعات التي تمارس نشاطها في المناطق الحرة، وكذا قانون التأمين على أصحاب الأعمال ومن في حكمهم الصادر بالقانون رقم 108 لسنة 1976."}, {"number": "46", "chapter": "الفصل الرابع", "text": "لا يجوز لأي شخص أن يزاول مهنة أو حرفة في المنطقة الحرة العامة لحسابه بصفة دائمة إلا بعد الحصول على تصريح بذلك من رئيس مجلس إدارة المنطقة طبقا للشروط والأوضاع التي تبينها اللائحة التنفيذية لهذا القانون وبعد سداد رسم سنوي لا يجاوز خمسة آلاف جنيه . ويعاقب بغرامة لا تقل عن خمسة آلاف جنيه ولا تجاوز عشرين ألف جنيه كل من يخالف حكم الفقرة الأولى من هذه المادة، ولا ترفع الدعوى الجنائية في هذه الحالة إلا بإذن الوزير المختص، وفي جميع الأحوال تحظر إقامة مشروعات تزاول المهن الحرة والاستشارات في المناطق الحرة، ويكون دخول المناطق الحرة وفقا للشروط التي يصدر بها قرار من مجلس إدارة الهيئة ."}, {"number": "47", "chapter": "الفصل الرابع", "text": "تسري على الاستثمار بنظام المناطق الحرة الأهداف، والمبادئ، والضمانات، والمادة (11) من هذا القانون فيما لا يتعارض مع طبيعة العمل بهذا النظام . ويجوز للمشروعات العاملة بهذا النظام التحول للعمل بنظام الاستثمار الداخلي، وتحدد اللائحة التنفيذية لهذا القانون شروط التحول وضوابطه والمعاملة الجمركية للمعدات والآلات وأجهزة الإنتاج وخطوطه وقطاع الغيار التي يقتضيها النشاط المرخص لها به ."}, {"number": "48", "chapter": "الفصل الخامس", "text": "مع مراعاة حكم المادة (71) من هذا القانون، تلتزم الهيئة بتقديم خدمات التأسيس وما بعد التأسيس ومركز خدمات المستثمرين للشركات الخاضعة لأحكام هذا القانون وقانون شركات المساهمة وشركات التوصية بالأسهم والشركات ذات المسئولية المحدودة الصادر بالقانون رقم 159 لسنة 1981، وميكنتها وتوحيد إجراءاتها، وتسري إجراءات التأسيس الإلكتروني دون غيرها فور تفعيلها بالهيئة، ولا تتقيد الهيئة في ذلك بأي إجراءات منصوص عليها في القوانين الأخرى . وتحدد اللائحة التنفيذية لهذا القانون الأحكام المنظمة لنشر النظام الأساسي للشركة وإجراءات تعديله وضوابط العمل بنظام التأسيس الإلكتروني والخدمات للشركات والمنشآت الخاضعة لأحكام هذا القانون، وقانون شركات المساهمة وشركات التوصية بالأسهم والشركات ذات المسئولية المحدودة المشار إليه ."}, {"number": "49", "chapter": "الفصل الخامس", "text": "يصدر بقرار من الوزير المختص نموذج عقد لكل نوع من أنواع الشركات ونظامها الأساسي بحسب الأحوال . ويسدد طالب التأسيس، دفعة واحدة، للهيئة جميع ما تفرضه التشريعات من الرسوم المقررة وغيرها من المبالغ للجهات التي تقدم الخدمات المتصلة بالتأسيس وما بعد التأسيس، وتحصل الهيئة هذه الرسوم لحساب تلك الجهات . وتستحق الهيئة مقابلاً لما تؤديه للمستثمرين من خدمات فعلية، ويصدر مجلس إدارة الهيئة قرارا بتحديد فئات هذا المقابل والقواعد والشروط والإجراءات المنظمة لتحصيله ."}, {"number": "50", "chapter": "الفصل الخامس", "text": "تلتزم الجهات المختصة بتوفيق أوضاعها لتفعيل نظام الخدمات الإلكترونية لدى الهيئة، وذلك بموافاتها بجميع المستندات والنماذج والبيانات وربط أنظمة العمل وقواعد البيانات لدى تلك الجهات بنظام الخدمات الإلكترونية بالهيئة وقاعدة بياناتها، وذلك خلال تسعين يوما من تاريخ العمل بأحكام هذا القانون . كما تلتزم الجهات المختصة بالاعتداد بالتوقيعات الإلكترونية والمستندات والنماذج المعدة بإحدى الوسائل التكنولوجية، وقبول السداد الإلكتروني لجميع مدفوعاتها، وذلك على النحو الذي تبينه اللائحة التنفيذية لهذا القانون ."}, {"number": "51", "chapter": "الفصل الخامس", "text": "تلتزم الهيئة بالبت في طلب التأسيس خلال يوم عمل كامل على الأكثر بعد تقديمه مستوفيا، وتكتسب الشركة الشخصية الاعتبارية بمجرد قيدها في السجل التجاري، ويصدر لها شهادة بالتأسيس، يحدد بياناتها قرار من الرئيس التنفيذي . وعلى جميع الجهات المختصة والبنوك والجهات ذات الصلة كافة الاعتداد بهذه الشهادة كمستند رسمي في تعاملاتها فور إصدارها . وتلتزم الشركات التي يتم تأسيسها وفقا لأحكام هذا القانون بتقديم شهادة تفيد إيداع الأوراق المالية للشركة لدى شركة إيداع مركزي . وتقوم الهيئة بوضع نظام يتيح إصدار شهادة للمشروع الاستثماري، يصدر بتنظيمها قرار من الرئيس التنفيذي للهيئة . كما يكون لكل منشأة أو شركة، أيا كان شكلها القانوني، رقم قومي موحد معتمد لجميع معاملات المستثمر مع أجهزة وجهات الدولة المختلفة كافة فور تفعيله . وذلك كله وفقا لما تبينه اللائحة التنفيذية لهذا القانون ."}, {"number": "52", "chapter": "الفصل الخامس", "text": "يجوز تحديد رأسمال الشركات الخاضعة لأحكام هذا القانون بأي عملة قابلة للتحويل وإعداد قوائمها المالية ونشرها بهذه العملة بشرط أن يكون الاكتتاب في رأسمالها بذات العملة، وبالنسبة لشركات الأموال يتم سداد النسبة المحددة من رأس المال المدفوع وفقا لأحكام قانون شركات المساهمة وشركات التوصية بالأسهم والشركات ذات المسئولية المحدودة الصادر بالقانون رقم 159 لسنة 1981 . كما يجوز تحويل مسمى رأسمال الشركات الخاضعة لأحكام هذا القانون من الجنيه المصري إلى أي عملة قابلة للتحويل، وفقا لسعر الصرف المعلن من البنك المركزي في تاريخ التحويل . وتحدد اللائحة التنفيذية لهذا القانون الضوابط المنظمة في هذا الشأن ."}, {"number": "53", "chapter": "الفصل الخامس", "text": "استثناء من أحكام المادة (45) من قانون شركات المساهمة وشركات التوصية بالأسهم والشركات ذات المسئولية المحدودة الصادر بالقانون رقم 159 لسنة 1981، يجوز تداول حصص التأسيس والأسهم لشركات الأموال الخاضعة لأحكام هذا القانون، خلال السنتين الماليتين الأوليين للشركة بموافقة الوزير المختص ."}, {"number": "54", "chapter": "الفصل الخامس", "text": "تلتزم الهيئة بإصدار القرارات التي تيسر على المستثمرين وتحقق سرعة تقديم الخدمات لهم في كل ما تختص به من إجراءات، ويكون لها في سبيل تحقيق ذلك، ودون التقيد بأي إجراءات منصوص عليها في القوانين الأخرى، وضع الضوابط التي تكفل فصل تنظيم إجراءات الاستثمار عن الرقابة اللاحقة على الشركات، بما لا يخل بمبادئ الشفافية والحوكمة والإدارة الرشيدة والمسئولية، وذلك من خلال الآتي : 1- تيسير جميع الإجراءات المتعلقة بالجمعيات العامة ومجالس إدارات الشركات والتصديق على محاضرها، بما في ذلك استخدام سبل التكنولوجيا الحديثة، بما لا يجاوز خمسة عشر يوما من تاريخ تقديمها مستوفاة . 2- الاستعاضة عن الدفاتر والمستندات بوسائل إلكترونية تتماشى مع التطور التكنولوجي . 3- تطوير وتوحيد وتبسيط إجراءات زيادة أو تخفيض رأس المال ونظم التقييم المالي، وإجراءات التحقق مما إذا كانت القيم المحددة لها قد قدرن تقديرا صحيحا، وذلك دون الإخلال بالاختصاص المقرر قانونا للهيئة العامة للرقابة المالية . وذلك كله وفقا لما تحدده اللائحة التنفيذية لهذا القانون ."}, {"number": "55", "chapter": "الفصل السادس", "text": "للمستثمر الحق في الحصول على العقارات اللازمة لمباشرة نشاطه أو التوسع فيه، أيا كانت نسبة مشاركته أو مساهمته في رأس المال، وذلك مع مراعاة القواعد الخاصة ببعض العقارات الواقعة في المناطق الجغرافية التي تنظمها قوانين خاصة، وذلك إما من خلال الجهة صاحبة الولاية على العقارات وفقا للقواعد المنصوص عليها في قوانينها ولوائحها بعد الإعلان عنها، أو من خلال الهيئة وفقا لأحكام التصرف المنصوص عليها في هذا القانون ."}, {"number": "56", "chapter": "الفصل السادس", "text": "تلتزم الجهات الإدارية صاحبة الولاية بعد التنسيق مع جميع الجهات المختصة والمركز الوطني لتخطيط استخدامات أراضي الدولة خلال تسعين يوما من تاريخ العمل بهذا القانون، بموافاة الهيئة بخرائط تفصيلية محددا عليها جميع العقارات الخاضعة لولايتها والمتاحة للاستثمار، بالإضافة إلى قاعدة بيانات كاملة تتضمن الموقع والمساحة والارتفاعات المقررة والسعر التقديري والأنشطة الاستثمارية الملائمة لطبيعتها وأسلوب التصرف فيها، كما تلتزم هذه الجهات بتحديث تلك البيانات دوريا كل ستة أشهر أو كلما طلبت الهيئة ذلك . ويصدر رئيس الجمهورية بعد موافقة مجلس الوزراء قرارا بنقل الملكية أو الولاية أو الإشراف على بعض العقارات، من الجهات الإدارية صاحبة الولاية إلى الهيئة متى استلزم تنفيذ الخطة الاستثمارية ذلك، على أن تتولى الهيئة التصرف فيها وفقا لأحكام هذا القانون ."}, {"number": "57", "chapter": "الفصل السادس", "text": "يكون التصرف للمستثمرين في العقارات المملوكة ملكية خاصة للدولة أو غيرها من الأشخاص الاعتبارية العامة بغرض الاستثمار طبقا للأحكام والضوابط والإجراءات المنصوص عليها في هذا القانون بمراعاة الخطة الاستثمارية للدولة، وحجم المشروع الاستثماري وطبيعة نشاطه، وقيمة الأموال المستثمرة فيه . ولا تسري على هذا التصرف أحكام قانون تنظيم المناقصات والمزايدات الصادر بالقانون رقم 89 لسنة 1998، إلا فيما لم يرد في شأنه نص خاص في هذا القانون وبما لا يتعارض مع أحكامه . وعلى المستثمر الالتزام بالجدول الزمني المقدم منه لتنفيذ المشروع الاستثماري المعتمد من الجهة المختصة، ما دامت تلك الجهة قد أوفت بالتزاماتها تجاه المستثمر . ولا يجوز للمستثمر إدخال تعديلات على المشروع الاستثماري بتعديل غرضه أو توسعته أو زيادة حجمه أو غير ذلك من تعديلات إلا بعد موافقة الجهة المختصة كتابة على ذلك سواء كان ذلك مباشرة أو من خلال ممثلها بمركز خدمات المستثمرين ."}, {"number": "58", "chapter": "الفصل السادس", "text": "مع مراعاة حكم المادة (37) من هذا القانون، يجوز التصرف في العقارات اللازمة للمشروعات الاستثمارية وفقا لأحكام هذا القانون بإحدى الصور الآتية: البيع، الإيجار، الإيجار المنتهي بالتملك، الترخيص بالانتفاع . ويكون ذلك إما بناء على طلب المستثمر، أو دعوة أو إعلان من الهيئة وفقا لأحكام هذا القانون . ويجوز للجهات الإدارية صاحبة الولاية على العقارات أن تشترك في المشروعات الاستثمارية بتلك العقارات كحصة عينية أو بالمشاركة في الأحوال التي يصدر بها قرار من مجلس الوزراء، وتبين اللائحة التنفيذية لهذا القانون أوضاع وإجراءات وكيفية اشتراك تلك الجهات بالعقارات في المشروع الاستثماري ."}, {"number": "59", "chapter": "الفصل السادس", "text": "في الأحوال التي يطلب فيها المستثمر توفير عقارات من أملاك الدولة الخاصة لإقامة مشروع استثماري، يتعين أن يبين في طلبه الغرض والمساحة والمكان الذي يرغب في إقامة المشروع عليه . وتتولى الهيئة عرض العقارات المتوفرة لديها أو لدى الجهات الإدارية صاحبة الولاية التي تلائم النشاط الاستثماري لطالب الاستثمار وبيان طبيعة العقار، والاشتراطات المتعلقة بها، وبيان ما إذا كانت مزودة بالمرافق وصور التصرف فيها، ومقابل ذلك، وغيرها من الاشتراطات والبيانات اللازمة ."}, {"number": "60", "chapter": "الفصل السادس", "text": "يجوز لأغراض التنمية دون غيرها وطبقاً للخريطة الاستثمارية، في المناطق التي يصدر بتحديدها قرار من رئيس الجمهورية بعد موافقة مجلس الوزراء، التصرف دون مقابل في العقارات المملوكة للدولة ملكية خاصة للمستثمرين الذين تتوافر فيهم الشروط الفنية والمالية التي يتم تحديدها بقرار من مجلس الوزراء، ويسري ذلك على صور التصرف المنصوص عليها في المادة (58) من هذا القانون . وفي جميع أحوال التصرف في العقارات دون مقابل، يجب على المستثمر تقديم ضمان نقدي أو ما يقوم مقامه إلى جهة التصرف بما لا يزيد على خمسة بالمائة (5%) من قيمة التكاليف الاستثمارية للمشروع، وذلك وفقاً للمعايير والضوابط التي تبينها اللائحة التنفيذية لهذا القانون، على أن يسترد ذلك الضمان بعد مرور ثلاث سنوات على بدء الإنتاج الفعلي للمشروعات ذات الطبيعة الإنتاجية، أو بدء مزاولة النشاط لغير ذلك من المشروعات، شريطة التزام المستثمر بشروط التصرف ."}, {"number": "61", "chapter": "الفصل السادس", "text": "في الحالات التي يكون فيها التصرف في العقارات بنظام الترخيص بالانتفاع بمقابل، يكون الترخيص مدة لا تزيد على خمسين عاماً قابلة للتجديد، بالشروط المتفق عليها ما دام المشروع مستمراً في نشاطه، ودون أن يخل ذلك بحق الجهة صاحبة الولاية في تعديل قيمة مقابل الانتفاع عند التجديد . ويكون الترخيص للمستثمرين الذين تتوفر فيهم الشروط الفنية والمالية التي تحددها الهيئة بالتنسيق مع الجهة الإدارية صاحبة الولاية . وتسري ذات الأحكام السابقة على أحوال التصرف بالتأجير ."}, {"number": "62", "chapter": "الفصل السادس", "text": "في الحالات التي يكون التصرف في العقارات بالبيع، يجوز لكل مستثمر لأغراض إقامة المشروعات الاستثمارية أو توسيعها أن يقدم طلباً بالتعاقد عليها، بشرط أن تتوفر فيه الشروط الفنية والمالية التي تحددها الهيئة بالتنسيق مع الجهة الإدارية صاحبة الولاية . ولا تنتقل ملكية العقارات إلى المستثمر في هذه الحالات إلا بعد سداد كامل الثمن وبدء الإنتاج الفعلي للمشروعات ذات الطبيعة الإنتاجية أو الانتهاء من تنفيذ المشروعات العقارية أو السياحية، أو بدء مزاولة النشاط لغير ذلك، ويجب أن يتضمن العقد المبرم مع المستثمر نصاً بذلك . ويجوز للهيئة بناءً على طلب المستثمر بعد موافقة الجهة الإدارية صاحبة الولاية، الاتفاق على تأجيل سداد كامل الثمن أو بعضه أو غير ذلك من التيسيرات إلى ما بعد التشغيل الفعلي للمشروع، ويحدد العقد ما يلزم لذلك من ضمانات وإجراءات . وتسري ذات الأحكام السابقة على نظام الإيجار المنتهي بالتملك ."}, {"number": "63", "chapter": "الفصل السادس", "text": "عند تزاحم طلبات المستثمرين في التعامل على العقارات اللازمة لإقامة مشروعات استثمارية سواء بنظام البيع أو التأجير أو التأجير المنتهي بالتملك أو الترخيص بالانتفاع، تكون المفاضلة بين من استوفى منهم الشروط الفنية والمالية اللازمة للاستثمار بنظام النقاط وفقاً لأسس مفاضلة من بينها قيمة العرض المقدم من المستثمر أو المواصفات الفنية أو المالية الأخرى . وإذا تعذرت المفاضلة بين المتزاحمين بنظام النقاط جاز إجراؤها وفقاً لأعلى سعر يقدم منهم . وتبين اللائحة التنفيذية لهذا القانون أحوال التزاحم، وضوابط إجراء تلك المفاضلة والأسس التي تتم بناءً عليها ."}, {"number": "64", "chapter": "الفصل السادس", "text": "في تطبيق أحكام هذا الفصل، يكون تقدير ثمن البيع أو القيمة الإيجارية أو مقابل الانتفاع عن طريق إحدى الجهات الآتية: الهيئة العامة للخدمات الحكومية، اللجنة العليا لتثمين أراضي الدولة بوزارة الزراعة، هيئة المجتمعات العمرانية الجديدة، الهيئة العامة للتنمية السياحية، الهيئة العامة للتنمية الصناعية، وذلك وفقاً لطبيعة النشاط المستهدف إقامته . وتلتزم جهة التقدير بضم ممثلين من ذوي الخبرة في عضوية لجان التقدير، وإنهاء عملية التقدير خلال مدة لا تجاوز ثلاثين يوماً من تاريخ تقديم طلب التقدير إليها . وتبين اللائحة التنفيذية لهذا القانون المعايير والضوابط والإجراءات اللازمة لمباشرة عملية التقدير، ومدة صلاحيته، والأتعاب التي يتم سدادها لجهة التسعير من الجهة صاحبة الولاية عند إتمام التخصيص ."}, {"number": "65", "chapter": "الفصل السادس", "text": "تشكل بقرار من الرئيس التنفيذي للهيئة وباعتماد من الوزير المختص لجنة أو أكثر تضم عناصر فنية ومالية وقانونية تتناسب وظائفهم وخبراتهم مع أهمية وطبيعة موضوع التعاقد، للبت في طلبات التصرف في العقارات للمستثمرين في الأحوال المختلفة وفقاً لأحكام هذا الفصل خلال مدة لا تجاوز ثلاثين يوماً من تاريخ ورود الرأي الفني في طلب المستثمر من جهة الولاية والذي يجب أن تقدمه جهة الولاية خلال أسبوع من تاريخ ورود الطلب، وتعتمد قراراتها منه، وتخطر الهيئة مقدم الطلب بهذا القرار . وتبين اللائحة التنفيذية لهذا القانون إجراءات عمل اللجان المشار إليها، وكيفية الإخطار وطرق سداد الثمن أو القيمة الإيجارية أو مقابل الانتفاع بحسب الأحوال، وأيلولة المستحقات إلى الجهات المختصة كاملة، كما تبين اللائحة التنفيذية إجراءات إعداد وتحرير العقود في كل حالة وفق نماذج العقود المعتمدة من مجلس إدارة الهيئة بعد مراجعتها من مجلس الدولة ."}, {"number": "66", "chapter": "الفصل السادس", "text": "في جميع الأحوال التي يتم فيها التصرف في العقارات المملوكة ملكية خاصة للدولة أو للأشخاص الاعتبارية العامة، يتعين على المشروع الاستثماري الالتزام بالغرض الذي تم التصرف في العقار على أساسه، ولا يجوز تغيير هذا الغرض إلا بعد الموافقة الكتابية من الجهة الإدارية صاحبة الولاية، في الأحوال التي تسمح فيها طبيعة العقار وموقعه بهذا التغيير وبشرط سداد المبالغ التي تبين اللائحة التنفيذية معايير تحديد قيمتها . وتلتزم هذه الجهة بالرد على طلب تغيير الغرض خلال ثلاثين يوماً من تاريخ تقديمه إليها وإلا اعتبر عدم الرد رفضاً للطلب . ويحق للمستثمر التظلم من هذا القرار أمام اللجنة المنصوص عليها بالمادة (83) من هذا القانون . وفي جميع الأحوال، لا يقبل طلب تغيير الغرض قبل انقضاء عام من تاريخ بدء الإنتاج أو مزاولة النشاط ."}, {"number": "67", "chapter": "الفصل السادس", "text": "يكون للجهة الإدارية صاحبة الولاية، بناءً على ما يقدم إليها من تقارير المتابعة التي يعدها موظفو الجهات الإدارية صاحبة الولاية بشأن متابعة مراحل تنفيذ البرنامج الزمني لإقامة منشآت المشروع الاستثماري، وبعد موافقة مجلس إدارة الهيئة، فسخ عقد البيع أو الإيجار أو الإيجار المنتهي بالتملك أو الترخيص بالانتفاع وسحب العقارات في أحد الأحوال الآتية : 1- الامتناع عن استلام العقار مدة تسعين يوماً من تاريخ إخطاره بالاستلام . 2- عدم البدء في تنفيذ المشروع خلال تسعين يوماً من تاريخ استلامه العقار خالياً من الموانع والعوائق بغير عذر مقبول واستمرار تقاعسه بعد إنذاره كتابة مدة مماثلة . 3- مخالفة شروط سداد المستحقات المالية ومواعيده . 4- تغيير غرض استخدام العقار الذي خصص له أو القيام برهنه أو ترتيب أي حق عيني عليه بغير الموافقة الكتابية المسبقة من الجهة الإدارية صاحبة الولاية أو قبل انتقال الملكية إليه وفقاً لأحكام هذا القانون . 5- مخالفة شروط العقد أو الترخيص بالانتفاع مخالفة جوهرية، في أي مرحلة من مراحل المشروع، وعدم إزالة أسباب المخالفة بعد إنذار المستثمر كتابة بذلك . وتبين اللائحة التنفيذية المخالفات الجوهرية المشار إليها وإجراءات استرداد العقارات في حالة ثبوت امتناع المستثمر أو تقاعسه عن إتمام تنفيذ المشروع ويجوز في هذه الحالة إعادة التصرف في العقار ."}, {"number": "68", "chapter": "الفصل الأول", "text": "ينشأ مجلس أعلى للاستثمار برئاسة رئيس الجمهورية، يختص فضلاً عما هو مقرر له في هذا القانون بالآتي : 1- اتخاذ كل ما يلزم لتهيئة مناخ أفضل للاستثمار والتوجيه بما يتطلبه ذلك . 2- وضع الإطار العام للإصلاح التشريعي والإداري لبيئة الاستثمار . 3- إقرار السياسات والخطة الاستثمارية التي تحدد أولويات مشروعات الاستثمار المستهدفة، بما يتفق مع السياسة العامة للدولة وخطة التنمية الاقتصادية والاجتماعية ونظم الاستثمار المطبقة . 4- متابعة تنفيذ أجهزة الدولة للخطط والبرامج المتعلقة بالاستثمار، وتطور العمل بالمشروعات الاقتصادية الكبرى، وموقف مشروعات المشاركة مع القطاع الخاص . 5- متابعة تحديث الخريطة الاستثمارية وتنفيذها على مستوى القطاعات المتخصصة والمناطق الجغرافية المختلفة، في إطار خطة التنمية الاقتصادية للدولة . 6- استعراض الفرص الاستثمارية المتاحة في كل قطاع وبحث محاور المشاكل المتعلقة بها . 7- متابعة تطور تصنيف مصر وترتيبها في التقارير والمؤشرات الدولية الخاصة بالاستثمار . 8- تابعة آليات تسوية منازعات الاستثمار وموقف قضايا التحكيم الدولي . 9- دراسة ووضع حلول لمعوقات الاستثمار وإزالة عقبات تنفيذ أحكام هذا القانون . 10- تفعيل المسئولية التضامنية لجميع الوزارات والهيئات العامة والأجهزة الحكومية المختصة بالاستثمار، وتحقيق التناغم في أدائها . 11- حل الخلافات والتشابكات التي قد تثور بين أجهزة الدولة في مجال الاستثمار . ويصدر بتشكيل هذا المجلس، وبنظام العمل به قرار من رئيس الجمهورية . وتلتزم جميع أجهزة الدولة بتنفيذ القرارات الصادرة عن المجلس ."}, {"number": "69", "chapter": "الفصل الثاني", "text": "الهيئة العامة للاستثمار والمناطق الحرة، هيئة عامة اقتصادية، لها شخصية اعتبارية عامة تتبع الوزير المختص، وتقوم على تنظيم الاستثمار في البلاد وتشجيعه، وتنمية وإدارة شئونه والترويج له، على النحو الذي يحقق خطة التنمية الاقتصادية للدولة . ويكون مقر الهيئة الرئيس محافظة القاهرة، ويجوز لها إنشاء فروع أو مكاتب لها داخل جمهورية مصر العربية أو خارجها بقرار من مجلس الإدارة ضمن بعثات التمثيل التجاري ."}, {"number": "70", "chapter": "الفصل الثاني", "text": "مع عدم الإخلال بأحكام قانون سوق رأس المال الصادر بالقانون رقم 95 لسنة 1992 والقانون رقم 95 لسنة 1995 في شأن التأجير التمويلي وقانون التمويل العقاري الصادر بالقانون رقم 148 لسنة 2001 وقانون البنك المركزي والجهاز المصرفي والنقد الصادر بالقانون رقم 88 لسنة 2003 والقانون رقم 10 لسنة 2009 بتنظيم الرقابة على الأسواق والأدوات المالية غير المصرفية، تكون الهيئة هي الجهة الإدارية المختصة دون غيرها بتطبيق أحكام هذا القانون وقانون شركات المساهمة وشركات التوصية بالأسهم والشركات ذات المسئولية المحدودة الصادر بالقانون رقم 159 لسنة 1981 . ولا تتقيد الهيئة في المسائل المالية والإدارية بالنظم والقواعد الحكومية، وللهيئة في سبيل إنجاز مهامها الاستعانة بأفضل الكفاءات والخبرات المحلية والعالمية، وذلك دون الإخلال بأحكام القانون رقم 63 لسنة 2014 بشأن الحد الأقصى لدخول العاملين بأجر لدى أجهزة الدولة، ويصدر بتنظيم هذه المسائل قرار من مجلس إدارة الهيئة . ويكون للهيئة في سبيل تحقيق أغراضها التعاقد وإجراء التصرفات والأعمال، ويجوز تخصيص عقارات من أملاك الدولة الخاصة أو إعادة تخصيصها للهيئة بغرض استخدامها في شئونها الإدارية ."}, {"number": "71", "chapter": "الفصل الثاني", "text": "للهيئة في سبيل تحقيق أغراضها، فضلاً عما هو منصوص عليه في هذا القانون، مباشرة الاختصاصات الآتية : 1- إعداد مشروع الخطة الاستثمارية بالتنسيق والتعاون مع جميع أجهزة الدولة المختصة تتضمن نوعية الاستثمار ونظامه، ومناطقه الجغرافية وقطاعاته، والعقارات المملوكة للدولة أو للأشخاص الاعتبارية العامة الأخرى المعدة للاستثمار، ونظام التصرف فيها وطريقته بحسب نوع النظام الاستثماري . 2- وضع الخطط والدراسات والنظم الكفيلة بجذب وتشجيع رءوس الأموال الوطنية والأجنبية للاستثمار في مختلف المجالات وفق الخطة الاستثمارية للدولة، واتخاذ الإجراءات اللازمة لذلك . 3- إعداد قاعدة بيانات وخريطة للفرص الاستثمارية المتاحة والمشروعات والأنشطة الاستثمارية المستهدفة، ومتابعة تحديثها، وتوفير هذه المعلومات والبيانات للمستثمرين . 4- إصدار الشهادة اللازمة لتمتع المستثمر بالحوافز والضمانات المنصوص عليها في هذا القانون . 5- وضع خطة للترويج للاستثمار واتخاذ جميع الإجراءات اللازمة لذلك بجميع الوسائل ونشرها في الداخل والخارج . 6- توحيد جميع النماذج الرسمية الخاصة بشئون الاستثمار بالتنسيق مع الجهات المختصة وتوفيرها للاستخدام من خلال الشبكة الدولية للمعلومات وغيرها من الوسائل . 7- وضع نظام لإدارة المناطق الحرة والاستثمارية بما يخدم الاقتصاد القومي . 8- دراسة التشريعات المتعلقة بالاستثمار واقتراح ما يلزم في شأنها ومراجعتها بشكل دوري . 9- إقامة المؤتمرات والندوات وورش التدريب والعمل والمعارض المتصلة بشئون الاستثمار وتنظيمها داخلياً وخارجياً . 10- التعاون مع المؤسسات والمنظمات الدولية والأجنبية العاملة في مجال الاستثمار والترويج له . 11- إجراء الرقابة والتفتيش على الشركات الخاضعة لأحكام هذا القانون، وذلك وفقاً للقواعد والإجراءات التي تبينها اللائحة التنفيذية لهذا القانون والقوانين الأخرى ."}, {"number": "72", "chapter": "الفصل الثاني", "text": "يجوز للهيئة لأغراض تنفيذ خطتها في مجال الترويج لفرص الاستثمار المتاحة داخلياً وخارجياً، أن تعهد بهذه المهمة إلى شركات متخصصة يتم التعاقد معها لهذا الغرض، دون التقيد بأحكام قانون تنظيم المناقصات والمزايدات الصادر بالقانون رقم 89 لسنة 1998، وذلك وفقاً للقواعد التي تبينها اللائحة التنفيذية لهذا القانون ."}, {"number": "73", "chapter": "الفصل الثاني", "text": "يكون للهيئة مجلس إدارة، يتولى وضع السياسة العامة لها والإشراف على تنفيذها، يشكل بقرار من رئيس مجلس الوزراء، على النحو الآتي : 1- الوزير المختص رئيساً . 2- الرئيس التنفيذي للهيئة . 3- نواب الرئيس التنفيذي للهيئة . 4- ثلاثة من ممثلي الجهات والأجهزة ذات الصلة . 5- اثنان من ذوي الخبرة أحدهما في مجال الاستثمار بالقطاع الخاص والثاني في مجال القانون . وتكون مدة العضوية ثلاث سنوات قابلة للتجديد . ويجتمع المجلس مرة على الأقل شهرياً، ولا يكون انعقاده صحيحاً إلا بحضور ثلثي الأعضاء على الأقل، وله أن يشكل من بين أعضائه لجنة أو أكثر يعهد إليها بمهمة محددة، ولرئيسه دعوة من يراه من الخبراء لحضور الاجتماعات كلما دعت الحاجة إلى ذلك . وتصدر قرارات المجلس بأغلبية الحاضرين من الأعضاء، وفي حالة تساوي الأصوات يرجح الجانب الذي منه الرئيس وتنظم اللائحة التنفيذية لهذا القانون نظام عمل المجلس . ويقوم أعضاء مجلس الإدارة بالإفصاح عن جميع أموالهم، على أن يتم تقديم ومراجعة هذا الإفصاح سنوياً من قبل جهة مستقلة للتحقق من عدم وجود مخالفة أو تضارب فعلي أو محتمل للمصالح، على أن يرفع هذا التقرير إلى المجلس الأعلى عن طريق الوزير المختص ."}, {"number": "74", "chapter": "الفصل الثاني", "text": "مجلس إدارة الهيئة هو السلطة العليا المهيمنة على شئونها، وعليه أن يتخذ ما يراه لازماً من قرارات لتحقيق الأغراض التي أنشئت الهيئة من أجلها طبقاً لأحكام هذا القانون ولائحته التنفيذية، ويتولى على الأخص ما يلي : 1- وضع خطط نشاط الهيئة وبرامجها في إطار السياسة الاستثمارية للدولة . 2- وضع آليات تفعيل منظومة مركز خدمات المستثمرين، ومتابعة تنفيذها . 3- تحديد مقابل الخدمات التي تقدمها الهيئة . 4- إقرار اللوائح الداخلية والقرارات التنفيذية المتعلقة بالشئون المالية والإدارية والفنية للهيئة، ووضع هيكلها التنظيمي . 5- إقرار مشروع الموازنة السنوية للهيئة وحساباتها الختامية . 6- وضع ضوابط تشكيل واختصاصات ونظم عمل مجالس إدارات المناطق الحرة والاستثمارية، على أن يصدر بالتشكيل والاختصاصات قرار من الرئيس التنفيذي للهيئة . 7- إقرار اللوائح والنظم واعتماد النماذج اللازمة لإقامة المناطق الحرة والاستثمارية وتنميتها وإدارتها، وتحديد ضوابط وآليات إلغاء المشروعات المقامة وفقاً لأنظمة الاستثمار المختلفة، والمدد اللازمة لسقوط الموافقات الصادرة بشأنها . 8- اعتماد شروط منح التراخيص وشغل العقارات واستردادها بما عليها من مبان وإنشاءات وما بداخلها وعلى الأخص ما يتعلق بالمناطق الاستثمارية وفقاً لأحكام هذا القانون . 9- اعتماد ضوابط قواعد دخول البضائع وخروجها وأحكام قيدها ومقابل شغل الأماكن التي تودع بها، وفحص المستندات والمراجعة والنظام الخاص برقابة المناطق الحرة وحراستها وتحصيل الرسوم المستحقة، وذلك بالتنسيق مع مصلحة الجمارك . 10- الموافقة على إنشاء فروع ومكاتب للهيئة لتفعيل مركز خدمات المستثمرين المنصوص عليه في هذا القانون وتقديم خدمات الاستثمار . 11- وضع نظام لميكنة خدمات الاستثمار التي تقدم من خلال الهيئة . 12- وضع النظم والقواعد التي تكفل تطبيق مبادئ. الحوكمة وأعمال قواعد التفتيش والرقابة اللاحقة على الشركات واتخاذ الإجراءات اللازمة لذلك على النحو الذي تبينه اللائحة التنفيذية لهذا القانون . 13- وضع نظام يكفل توفير الإحصاءات والبيانات والمعلومات اللازمة لمزاولة المشروع الاستثماري لنشاطه، وذلك دون الإخلال باعتبارات الأمن القومي أو الحق في الخصوصية وسرية المعلومات أو بحماية حقوق الغير، ويجب على جميع الجهات المختصة إمداد الهيئة بما يتطلبه وضع هذا النظام ."}, {"number": "75", "chapter": "الفصل الثاني", "text": "تتكون موارد الهيئة مما يأتي : 1- الاعتمادات المالية التي تخصصها لها الدولة . 2- الرسوم ومقابل الخدمات التي تحصلها الهيئة عدا تلك التي تحصلها لحساب الجهات الأخرى . 3- الهبات والمنح والقروض المحلية والخارجية التي يوافق عليها مجلس إدارة الهيئة طبقاً للقواعد المقررة في هذا الشأن . 4- مقابل شغل العقارات المملوكة أو المخصصة للهيئة . 5- أي موارد أخرى يصدر بها قرار من مجلس إدارة الهيئة بعد موافقة مجلس الوزراء ."}, {"number": "76", "chapter": "الفصل الثاني", "text": "يكون للهيئة موازنة مستقلة تعد على نمط موازنات الهيئات الاقتصادية، وتبدأ السنة المالية للهيئة مع السنة المالية للدولة وتنتهي بانتهائها، وتخضع حساباتها وأرصدتها وأموالها لرقابة الجهاز المركزي للمحاسبات وتودع جميع موارد الهيئة في حساب خاص تحت حساب الخزانة الموحد بالبنك المركزي المصري، ويرحل فائض الموازنة من سنة إلى أخرى إلى الحساب الخاص، ويصرف من الحساب بقرار من مجلس إدارة الهيئة ."}, {"number": "77", "chapter": "الفصل الثاني", "text": "يصدر بتعيين الرئيس التنفيذي للهيئة ونوابه وتحديد معاملتهم المالية قرار من رئيس مجلس الوزراء بناءً على عرض الوزير المختص، وذلك لمدة ثلاث سنوات قابلة للتجديد لمدة واحدة، ولا يجوز أن يزيد عدد نواب رئيس الهيئة على خمسة نواب، وتحدد اختصاصات نواب الرئيس التنفيذي بقرار من الوزير المختص . ويتولى الرئيس التنفيذي للهيئة تمثيلها أمام القضاء والغير، كما يتولى تصريف شئونها وتنفيذ قرارات مجلس إدارتها، وله في سبيل ذلك اتخاذ ما يلزم لتيسير إجراءات الخدمات التي تقدمها الهيئة للمستثمرين، وكذا اتخاذ ما يلزم لتفعيل نظام الرقابة والشفافية والحوكمة والإدارة الرشيدة . ويجوز للرئيس التنفيذي تفويض أحد نوابه في بعض اختصاصاته دون أن يتضمن التفويض تمثيل الهيئة أمام القضاء أو الغير . وتبين اللائحة التنفيذية الاختصاصات والمهام الأخرى للرئيس التنفيذي ."}, {"number": "78", "chapter": "الفصل الثاني", "text": "على الرئيس التنفيذي إعداد خطة سنوية، وإستراتيجية مستدامة للهيئة كل خمس سنوات، وتقرير نصف سنوي يتضمن بياناً بنتائج أعمالها وما أنجزته في سبيل تيسير إجراءات الاستثمار والترويج له، للعرض على مجلس إدارة الهيئة . ويقدم الوزير المختص إلى كل من المجلس الأعلى ومجلس الوزراء الخطة السنوية للهيئة والتقرير المشار إليه، وما يتضمنه من نتائج، في ضوء خطة الهيئة السنوية أو إستراتيجيتها الخمسية وما أنجزته في مجال تيسير إجراءات الاستثمار والترويج له وأبرز معوقات الاستثمار، وما تقترحه الوزارة المختصة من سياسات وإجراءات وتعديلات تشريعية لتحسين مناخ الاستثمار في الدولة . ويجوز للرئيس التنفيذي عند الضرورة وبعد موافقة مجلس إدارة الهيئة الموافقة على استكمال أو تطوير مقومات البنية الأساسية للمناطق الحرة العامة غير المملوكة للهيئة، على أن تئول إليها قيمة ما أنفقته خصماً من مقابل الانتفاع الذي يحصل من المشروعات المقامة بتلك المناطق لصالح الجهة مالكة الأرض . وتبين اللائحة التنفيذية لهذا القانون ضوابط الاستكمال أو التطوير المشار إليهما، وأسس تحديد قيمة ما تم إنفاقه وطرق استرداده ."}, {"number": "79", "chapter": "الفصل الثاني", "text": "تقوم الهيئة سنوياً بنشر قائمة الشركات التي تستفيد من الحوافز المنصوص عليها في هذا القانون في تقرير تنشره على موقعها الإلكتروني يتضمن طبيعة النشاط وموقعه وطبيعة الحوافز وأسماء الشركاء أو المساهمين أو مالكي الشركة . كما تلتزم الهيئة سنوياً بنشر قائمة الشركات المستفيدة من أراضي الدولة بموجب أحكام هذا القانون، في تقرير يتضمن غرض استخدام الأرض وطبيعتها وأبعادها وموقعها بدقة، وتقييم الخبراء، وأسماء الشركاء والمساهمين أو أصحاب الشركة . وتلتزم الشركات بتقديم بيان بحجم استثماراتها والقوائم المالية السنوية وبيان بعدد العاملين ووظائفهم وجنسياتهم ومجموع أجورهم وغير ذلك من بيانات تحددها اللائحة التنفيذية لهذا القانون ."}, {"number": "80", "chapter": "الفصل الثاني", "text": "يكون لموظفي الهيئة ممن يصدر بتحديدهم قرار من وزير العدل بالاتفاق مع الوزير المختص صفة مأموري الضبط القضائي في إثبات الجرائم التي ترتكب بالمخالفة لأحكام هذا القانون وقانون شركات المساهمة وشركات التوصية بالأسهم والشركات ذات المسئولية المحدودة الصادر بالقانون رقم 159 لسنة 1981 والقرارات المنفذة لهما، ولهم في سبيل ذلك دخول المشروعات الاستثمارية الخاضعة لأحكام هذا القانون للاطلاع على مستنداتها وسجلاتها، وذلك بقرار من الرئيس التنفيذي على أن يعرض عليه تقرير بنتائج أعمالهم، وعلى المشروعات الاستثمارية المعنية تسهيل مهمتهم ."}, {"number": "81", "chapter": "الفصل الثاني", "text": "في حالة مخالفة الشركات أو المنشآت لأحكام هذا القانون، تقوم الهيئة بإنذار الشركات أو المنشآت فوراً لإزالة أسباب المخالفة في مدة لا تجاوز خمسة عشر يوم عمل من تاريخ الإنذار . ويتضمن الإنذار المدة المحددة لإزالة أسباب المخالفة، فإذا انقضت هذه المدة دون ذلك كان للرئيس التنفيذي للهيئة بعد موافقة مجلس الإدارة إصدار قرار بإيقاف نشاط الشركة أو المنشأة مدة لا تجاوز تسعين يوماً، فإذا استمرت الشركة أو المنشأة في ارتكاب المخالفة أو الاستمرار فيها أو ارتكبت مخالفة أخرى خلال سنة من المخالفة الأولى جاز اتخاذ أحد الإجراءات الآتية : (أ) إيقاف التمتع بالحوافز والإعفاءات المقررة . (ب) تقصير مدة التمتع بالحوافز والإعفاءات المقررة . (جـ) إنهاء التمتع بالحوافز والإعفاءات المقررة، مع ما يترتب على ذلك من آثار بالنسبة للقرارات والتراخيص الصادرة للشركات والمنشآت . (د) إلغاء ترخيص مزاولة النشاط . وبالنسبة للمخالفات التي تهدد الصحة العامة أو أمن المواطنين أو الأمن القومي يكون للرئيس التنفيذي للهيئة بعد إخطار مجلس إدارة الهيئة إصدار قرار بإيقاف النشاط مدة تسعين يوماً، فإذا استمرت الشركة أو المنشأة في ارتكاب المخالفة أو ارتكبت مخالفة أخرى خلال سنة من المخالفة الأولى كان له إلغاء الترخيص ."}, {"number": "82", "chapter": "الباب الخامس", "text": "مع عدم الإخلال بالحق في التقاضي، تجوز تسوية أي نزاع ينشأ بين المستثمر وأي جهة أو أكثر من الجهات الحكومية يتعلق برأسمال المستثمر أو بتفسير أحكام هذا القانون أو تطبيقه ودياً دون تأخير من خلال المفاوضات بين الأطراف المتنازعة ."}, {"number": "83", "chapter": "الفصل الأول", "text": "تنشأ بالهيئة لجنة أو أكثر لنظر التظلمات من القرارات الصادرة وفقاً لأحكام هذا القانون من الهيئة أو الجهات المختصة بمنح الموافقات والتصاريح والتراخيص . وتشكل اللجنة برئاسة مستشار من إحدى الجهات القضائية تحدده المجالس الخاصة بتلك الجهات وعضوية ممثل عن الهيئة وأحد ذوي الخبرة . ويصدر بتشكيل اللجنة ونظام عملها وأمانتها الفنية قرار من الوزير المختص ."}, {"number": "84", "chapter": "الفصل الأول", "text": "تقدم التظلمات إلى اللجنة خلال خمسة عشر يوم عمل من تاريخ الإخطار أو العلم بالقرار المتظلم منه ويترتب على تقديم التظلم انقطاع مواعيد الطعن، وللجنة الاتصال بذوي الشأن والجهات الإدارية المختصة لطلب تقديم الإيضاحات والمستندات والإجابة على الاستفسارات التي تراها لازمة، ولها أن تستعين بالخبرات والتخصصات المختلفة بالهيئة وغيرها من الجهات الإدارية . وتفصل اللجنة فيما يعرض عليها بقرار مسبب خلال ثلاثين يوماً من تاريخ انتهاء سماع الأطراف وتقديم وجهات نظرهم، ويكون قرارها في هذا الشأن نهائياً وملزماً لجميع الجهات المختصة، وذلك دون إخلال بحق المستثمر في اللجوء إلى القضاء . وتبين اللائحة التنفيذية مكان انعقاد اللجنة وكيفية الإخطار بقراراتها ."}, {"number": "85", "chapter": "الفصل الثاني", "text": "تنشأ لجنة وزارية تسمى \"اللجنة الوزارية لفض منازعات الاستثمار\"، تختص بالنظر فيما يقدم أو يحال إليها من طلبات أو شكاوي أو منازعات قد تنشأ بين المستثمرين والدولة أو تكون إحدى الجهات أو الهيئات أو الشركات التابعة لها طرفاً فيها . ويصدر بتشكيل اللجنة قرار من رئيس مجلس الوزراء، ويشارك في عضويتها أحد نواب رئيس مجلس الدولة يختاره المجلس الخاص للشئون الإدارية بمجلس الدولة، وتعتمد قراراتها من مجلس الوزراء، ويجوز للوزراء من أعضاء اللجنة في حالة الضرورة إنابة من يمثلهم لحضور اجتماع اللجنة والتصويت على قراراتها فيه . ويكون للجنة أمانة فنية، يصدر بتشكيلها ونظام عملها قرار من الوزير المختص ."}, {"number": "86", "chapter": "الفصل الثاني", "text": "يشترط لصحة انعقاد اللجنة حضور رئيسها ونصف أعضائها الأصليين على الأقل، وتصدر اللجنة قراراتها بأغلبية أصوات الحاضرين، وعند تساوي الأصوات يرجح الجانب الذي منه الرئيس . وتلتزم الجهة الإدارية المختصة بتقديم المذكرات الشارحة والمستندات اللازمة بمجرد طلبها، وإذا كانت هذه الجهة من الجهات المشتركة في عضوية اللجنة فلا يكون لها صوت معدود في المداولات بالنسبة للموضوع المتعلق بها . وتفصل اللجنة فيما يعرض عليها بقرار مسبب خلال ثلاثين يوماً من تاريخ انتهاء سماع الأطراف وتقديم وجهات نظرهم ."}, {"number": "87", "chapter": "الفصل الثاني", "text": "مع عدم الإخلال بحق المستثمر في اللجوء إلى القضاء، تكون قرارات اللجنة بعد اعتمادها من مجلس الوزراء واجبة النفاذ وملزمة للجهات الإدارية المختصة ولها قوة السند التنفيذي، ويترتب على الامتناع عن تنفيذ قراراتها تطبيق أحكام المادة 123 من قانون العقوبات وتوقيع العقوبة المقررة بها. ولا يترتب على تقديم التظلم في قرارات اللجنة وقف تنفيذها ."}, {"number": "88", "chapter": "الفصل الثالث", "text": "تنشأ بمجلس الوزراء لجنة وزارية، تسمى \" اللجنة الوزارية لتسوية منازعات عقود الاستثمار\"، تختص بتسوية المنازعات الناشئة عن عقود الاستثمار التي تكون الدولة أو إحدى الجهات أو الهيئات أو الشركات التابعة لها طرفاً فيها . وتشكل هذه اللجنة بقرار من رئيس مجلس الوزراء، ويشارك في عضويتها أحد نواب رئيس مجلس الدولة يختاره المجلس الخاص للشئون الإدارية بمجلس الدولة، وتعتمد قراراتها من مجلس الوزراء، ولا تجوز الإنابة في حضور جلساتها . ويشترط لصحة انعقاد اللجنة حضور رئيسها ونصف عدد أعضائها، وتصدر اللجنة قراراتها بأغلبية الآراء وعند تساوي الأصوات يرجح الجانب الذي منه الرئيس . ويكون للجنة أمانة فنية يصدر بتشكيلها ونظام عملها قرار من رئيس مجلس الوزراء ."}, {"number": "89", "chapter": "الفصل الثالث", "text": "تتولى اللجنة بحث الخلافات الناشئة بين أطراف عقود الاستثمار ودراستها، ويكون لها في سبيل ذلك وبرضاء أطراف التعاقد إجراء التسوية اللازمة لمعالجة اختلال توازن تلك العقود، ومد الآجال أو المدد أو المهل المنصوص عليها فيها . كما تتولى متى لزم الأمر، إعادة جدولة المستحقات المالية أو تصحيح الإجراءات السابقة على إبرام العقود، وذلك كله على نحو يحقق قدر الإمكان التوازن العقدي ويضمن الوصول إلى أفضل وضع اقتصادي للحفاظ على المال العام وحقوق المستثمر في ضوء ظروف كل حالة . وتعرض اللجنة تقريراً بما تتوصل إليه بشأن حالة التسوية على مجلس الوزراء يبين جميع عناصرها، وتكون تلك التسوية بعد اعتمادها من مجلس الوزراء واجبة النفاذ وملزمة للجهات الإدارية المختصة ولها قوة السند التنفيذي ."}, {"number": "90", "chapter": "الفصل الرابع", "text": "تجوز تسوية منازعات الاستثمار المتعلقة بتنفيذ أحكام هذا القانون بالطريقة التي يتفق عليها مع المستثمر أو وفقاً لأحكام قانون التحكيم في المواد المدنية والتجارية الصادر بالقانون رقم 27 لسنة 1994 كما يجوز للطرفين، في أي وقت من الأوقات خلال النزاع، الاتفاق على التماس سبل التسوية بمختلف أنواعها طبقاً للقواعد المعمول بها لتسوية المنازعات، بما في ذلك اللجوء إلى التحكيم غير المؤسسي (الحر)، أو التحكيم المؤسسي ."}, {"number": "91", "chapter": "الفصل الرابع", "text": "ينشأ مركز مستقل للتحكيم والوساطة يسمى (المركز المصري للتحكيم والوساطة) تكون له الشخصية الاعتبارية، ويتخذ من محافظة القاهرة مقراً له . ويتولى المركز تسوية منازعات الاستثمار التي قد تنشأ بين المستثمرين، أو بينهم وبين الدولة أو إحدى الجهات التابعة لها عامة أو خاصة، إذا ما اتفقوا في أي مرحلة على تسوية النزاع عن طريق التحكيم أو الوساطة أمام هذا المركز، وذلك كله مع مراعاة أحكام القوانين المصرية المنظمة للتحكيم وتسوية المنازعات . ويتولى إدارة المركز مجلس إدارة، يتكون من خمسة أعضاء من ذوي الخبرة والتخصص والكفاءة والسمعة الطيبة يصدر بتعيينهم قرار من رئيس مجلس الوزراء . وتكون مدة مجلس الإدارة خمس سنوات يجوز تجديدها مرة واحدة، ولا يجوز عزل أحد أعضاء مجلس الإدارة طوال هذه المدة إلا إذا فقد الصلاحية الطبية لممارسة مهام عمله، أو فقد الثقة والاعتبار، أو أخل إخلالاً جسيماً بواجبات عمله وفقاً للنظام الأساسي للمركز . وينتخب أعضاء مجلس الإدارة من بينهم رئيساً للمجلس، ويكون للمركز مدير تنفيذي، يصدر بتعيينه وتحديد معاملته المالية قرار من مجلس الإدارة . ويصدر بالنظام الأساسي لهذا المركز ونظام العمل فيه والقواعد المهنية والإجراءات المنظمة له ومقابل الخدمات التي يقدمها وقوائم المحكمين والوسطاء وأتعابهم، قرار من مجلس إدارة المركز، وينشر النظام الأساسي للمركز في الوقائع المصرية . وتتكون موارد المركز المالية من مقابل الخدمات التي يقدمها وفقاً لما يحدده النظام الأساسي له . وتوفر في الثلاث سنوات الأولى من تاريخ العمل بهذا القانون موارد مالية كافية للمركز من الخزانة العامة للدولة، ولا يجوز للمركز بخلاف ما تقدم الحصول على أي أموال من الدولة أو إحدى أجهزتها ."}, {"number": "92", "chapter": "الفصل الرابع", "text": "في الأحوال التي ترتكب فيها الجريمة باسم الشخص الاعتباري الخاص ولحسابه، لا يعاقب المسئول عن الإدارة الفعلية إلا إذا ثبت علمه بالجريمة واتجهت إرادته لارتكابها تحقيقاً لمصلحة نفسه أو غيره، وذلك دون الإخلال بأحكام المسئولية المدنية . وفي الحالة التي لا تثبت فيها مسئولية الشخص الطبيعي على النحو المحدد في الفقرة السابقة، يعاقب الشخص الاعتباري بغرامة لا تقل عن أربعة أمثال الغرامة المقررة قانوناً للجريمة ولا تجاوز عشرة أمثالها، وفي حالة العود يحكم بإلغاء الترخيص أو حل الشخص الاعتباري بحسب الأحوال، وينشر الحكم في جريدتين يوميتين واسعتي الانتشار على نفقة الشخص الاعتباري ."}, {"number": "93", "chapter": "الفصل الرابع", "text": "في غير حالة التلبس، يكون طلب رفع الدعوى الجنائية في الجرائم المنصوص عليها في قانون الجمارك الصادر بالقانون رقم 66 لسنة 1963، وقانون الضريبة على الدخل الصادر بالقانون رقم 91 لسنة 2005، وقانون الضريبة على القيمة المضافة الصادر بالقانون رقم 67 لسنة 2016، بعد أخذ رأي الوزير المختص إذا كان المتهم بارتكاب الجريمة تابعاً لأحد المشروعات الاستثمارية الخاضعة لأحكام هذا القانون . ويتعين على الوزير المختص إبداء الرأي في هذا الشأن خلال سبعة أيام من تاريخ ورود كتاب استطلاع الرأي إليه، وإلا جاز رفع الدعوى طبقاً للقواعد المقررة في القوانين المشار إليها ."}, {"number": "94", "chapter": "الفصل الرابع", "text": "مع عدم الإخلال بحكم المادة (131) من قانون البنك المركزي والجهاز المصرفي والنقد الصادر بالقانون رقم 88 لسنة 2003، والمادة السادسة عشرة من القانون رقم 10 لسنة 2009 بتنظيم الرقابة على الأسواق والأدوات المالية غير المصرفية، لا يجوز رفع الدعوى الجنائية أو اتخاذ أي إجراء من إجراءات التحقيق قبل المستثمر في الجرائم المنصوص عليها في الباب الرابع من الكتاب الثاني من قانون العقوبات، إلا بعد أخذ رأي الوزير المختص على النحو المنصوص عليه في المادة (93) من هذا القانون وبالقواعد ذاتها ."}]};